{
  "name": "Stickman Legends: Dual Chaos",
  "description": "A high-octane 2-player co-op stickman brawler. Fight through endless waves of enemies, unlock high scores, and receive tactical AI analysis."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  PAUSED
}

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number; // For animation visual
  type: 'player' | 'enemy';
  playerIndex?: number; // 0 or 1
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
}

export interface GameStats {
  score: number;
  wave: number;
  enemiesKilled: number;
  timeSurvived: number;
}

import { GoogleGenAI } from "@google/genai";
import { GameStats } from "../types";

const createClient = () => {
  // Use the API Key from the environment
  const apiKey = process.env.API_KEY || '';
  if (!apiKey) {
    console.warn("API Key not found. AI features will be disabled.");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

export const getTacticalAnalysis = async (stats: GameStats): Promise<string> => {
  const client = createClient();
  if (!client) return "Tactical uplink offline. (Missing API Key)";

  try {
    const prompt = `
      You are a battle-hardened Stickman Commander.
      Analyze the following battle report for a failed mission:
      - Wave reached: ${stats.wave}
      - Enemies neutralized: ${stats.enemiesKilled}
      - Survival time: ${Math.floor(stats.timeSurvived)} seconds.
      - Score: ${stats.score}

      Give a short, punchy, 2-sentence breakdown.
      The first sentence should be a gritty observation of their failure.
      The second sentence should be tactical advice for the next run (e.g., "Don't let them flank you" or "Prioritize jumping").
      Keep it under 50 words. Be motivating but tough.
    `;

    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "Mission failed. Re-calibration required.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Communication jammed. Good luck next time, soldier.";
  }
};

import React from 'react';
import { GameState } from '../types';

