        <h1 className="text-8xl font-comic text-transparent bg-clip-text bg-gradient-to-r from-red-500 via-yellow-400 to-red-500 drop-shadow-[0_5px_5px_rgba(255,255,255,0.2)]">
          STICKMAN
        </h1>
        <h2 className="text-6xl font-comic text-white mt-[-10px] drop-shadow-lg">
          DUAL CHAOS
        </h2>
      </div>

      <div className="flex flex-col gap-4 w-64">
        <button
          onClick={() => {
            setPlayerCount(1);
            setGameState(GameState.PLAYING);
          }}
          className="group relative px-6 py-3 font-bold text-white transition-all duration-300 ease-out bg-gray-800 rounded-lg hover:bg-blue-600 hover:scale-105 active:scale-95"
        >
          <span className="absolute inset-0 w-full h-full -mt-1 rounded-lg opacity-30 bg-gradient-to-b from-transparent via-transparent to-black"></span>
          <span className="relative flex items-center justify-center gap-2">
            SOLO ASSAULT
          </span>
        </button>

        <button
          onClick={() => {
            setPlayerCount(2);
            setGameState(GameState.PLAYING);
          }}
          className="group relative px-6 py-3 font-bold text-white transition-all duration-300 ease-out bg-gray-800 rounded-lg hover:bg-orange-500 hover:scale-105 active:scale-95"
        >
          <span className="absolute inset-0 w-full h-full -mt-1 rounded-lg opacity-30 bg-gradient-to-b from-transparent via-transparent to-black"></span>
          <span className="relative flex items-center justify-center gap-2">
            CO-OP WARFARE (2P)
          </span>
        </button>
      </div>

      <div className="mt-12 text-sm text-gray-400 grid grid-cols-2 gap-12 text-center">
        <div>
          <h3 className="text-blue-400 font-bold mb-2">PLAYER 1</h3>
          <p>WASD to Move</p>
          <p>SPACE to Attack</p>
        </div>
        <div>
          <h3 className="text-orange-400 font-bold mb-2">PLAYER 2</h3>
          <p>ARROWS to Move</p>
          <p>ENTER (Return) to Attack</p>
        </div>
      </div>
    </div>
  );
};

export default MainMenu;

import React from 'react';
import { Entity, GameStats } from '../types';

interface GameUIProps {
  stats: GameStats;
  players: Entity[];
}

const HealthBar: React.FC<{ hp: number; maxHp: number; color: string; label: string }> = ({ hp, maxHp, color, label }) => {
  const pct = Math.max(0, (hp / maxHp) * 100);
  return (
    <div className="flex flex-col w-48">
      <div className="flex justify-between text-xs font-bold text-white mb-1 uppercase tracking-wider">
        <span>{label}</span>
        <span>{Math.ceil(hp)}/{maxHp}</span>
      </div>
      <div className="h-4 bg-gray-800 border-2 border-gray-600 skew-x-[-12deg] overflow-hidden relative">
        <div
          className={`h-full transition-all duration-200 ease-out ${color}`}
          style={{ width: `${pct}%` }}
        />
        {/* Shine effect */}
        <div className="absolute top-0 left-0 w-full h-1/2 bg-white/10"></div>
      </div>
    </div>
  );
};

const GameUI: React.FC<GameUIProps> = ({ stats, players }) => {
  return (
    <div className="absolute inset-0 pointer-events-none p-6 flex flex-col justify-between">
      {/* Top Bar */}
      <div className="flex justify-between items-start">
        {/* P1 Health */}
        {players[0] && !players[0].isDead ? (
           <HealthBar hp={players[0].health} maxHp={players[0].maxHealth} color="bg-blue-500" label="Player 1" />
        ) : (
           <div className="text-red-600 font-bold uppercase animate-pulse">P1 KIA</div>
        )}

        {/* Stats Center */}
        <div className="flex flex-col items-center">
          <div className="font-comic text-5xl text-yellow-400 drop-shadow-md">
            {stats.score.toLocaleString()}
          </div>
          <div className="bg-gray-800/80 px-4 py-1 rounded-full text-white text-sm font-bold border border-gray-600">
            WAVE {stats.wave}
          </div>
        </div>

        {/* P2 Health */}
        {players.length > 1 ? (
          players[1] && !players[1].isDead ? (
             <HealthBar hp={players[1].health} maxHp={players[1].maxHealth} color="bg-orange-500" label="Player 2" />
          ) : (
            <div className="text-red-600 font-bold uppercase animate-pulse">P2 KIA</div>
          )
        ) : <div className="w-48"></div>}
      </div>

      {/* Bottom info if needed */}
      <div className="text-center opacity-50 text-xs text-white">
        Stickman Legends v1.0
      </div>
    </div>
  );
};

export default GameUI;

import React, { useEffect, useState } from 'react';
import { GameState, GameStats } from '../types';
import { getTacticalAnalysis } from '../services/geminiService';

interface GameOverProps {
  stats: GameStats;
  onRestart: () => void;
  onMenu: () => void;
}

const GameOver: React.FC<GameOverProps> = ({ stats, onRestart, onMenu }) => {
  const [analysis, setAnalysis] = useState<string>("Establishing uplink to HQ...");

  useEffect(() => {
    let mounted = true;
    getTacticalAnalysis(stats).then(text => {
      if (mounted) setAnalysis(text);
    });
    return () => { mounted = false; };
  }, [stats]);

  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-sm">
      <div className="max-w-2xl w-full p-8 border border-red-900/50 bg-gradient-to-b from-gray-900 to-black rounded-xl shadow-2xl relative overflow-hidden">
        {/* Background Grid decorative */}
        <div className="absolute inset-0 opacity-10"
             style={{ backgroundImage: 'radial-gradient(circle, #333 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
        </div>

        <div className="relative z-10 text-center">
          <h2 className="text-6xl font-comic text-red-600 mb-2 tracking-widest uppercase drop-shadow-[0_0_10px_rgba(220,38,38,0.5)]">
            Mission Failed
          </h2>

          <div className="grid grid-cols-3 gap-4 my-8 p-6 bg-gray-800/30 rounded-lg border border-gray-700">
             <div className="flex flex-col">
               <span className="text-gray-400 text-sm uppercase">Score</span>
               <span className="text-2xl font-bold text-white">{stats.score}</span>
             </div>
             <div className="flex flex-col">
               <span className="text-gray-400 text-sm uppercase">Wave</span>
               <span className="text-2xl font-bold text-yellow-400">{stats.wave}</span>
             </div>
             <div className="flex flex-col">
               <span className="text-gray-400 text-sm uppercase">Kills</span>
               <span className="text-2xl font-bold text-red-400">{stats.enemiesKilled}</span>
             </div>
          </div>

          <div className="mb-8 text-left bg-gray-900/80 p-4 rounded border-l-4 border-blue-500">
            <h3 className="text-blue-400 text-xs font-bold uppercase tracking-wider mb-2 flex items-center gap-2">
              <span className="w-2 h-2 bg-blue-500 rounded-full animate-ping"></span>
              HQ Tactical Analysis
            </h3>
            <p className="text-gray-300 font-mono text-sm leading-relaxed typing-effect">
              {analysis}
            </p>
          </div>

          <div className="flex justify-center gap-4">
            <button
              onClick={onRestart}
              className="px-8 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded transition-colors uppercase tracking-widest"
            >
              Retry Mission
            </button>
            <button
              onClick={onMenu}
              className="px-8 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded transition-colors uppercase tracking-widest"
            >
              Main Menu
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GameOver;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats } from '../types';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  playerCount: number;
}

const GRAVITY = 0.8;
const FRICTION = 0.85;
const MOVE_SPEED = 1.2; // Acceleration
const JUMP_FORCE = -16;
const GROUND_Y = 500; // Floor position
const ATTACK_COOLDOWN = 30; // Frames
const ATTACK_RANGE = 70;
const ATTACK_DAMAGE = 25;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, playerCount }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  // Mutable Game State Refs (for performance in loop)
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 });
  const waveInProgressRef = useRef<boolean>(false);
  const spawnTimerRef = useRef<number>(0);

  // Initialize Game
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // Player 1
    newEntities.push({
      id: 'p1',
      type: 'player',
      playerIndex: 0,
      pos: { x: 200, y: GROUND_Y },
      vel: { x: 0, y: 0 },
      width: 30,
      height: 60,
      color: '#3b82f6', // Blue
      isGrounded: false,
      health: 100,
      maxHealth: 100,
      isDead: false,
      facingRight: true,
      attackCooldown: 0,
      isAttacking: false,
      attackFrame: 0,
    });

    // Player 2
    if (playerCount === 2) {
      newEntities.push({
        id: 'p2',
        type: 'player',
        playerIndex: 1,
        pos: { x: 300, y: GROUND_Y },
        vel: { x: 0, y: 0 },
        width: 30,
        height: 60,
        color: '#f97316', // Orange
        isGrounded: false,
        health: 100,
        maxHealth: 100,
        isDead: false,
        facingRight: true,
        attackCooldown: 0,
        isAttacking: false,
        attackFrame: 0,
      });
    }

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 };
    waveInProgressRef.current = true;
    spawnTimerRef.current = 0;

    // Sync UI state
    setStats(statsRef.current);
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  }, [playerCount, setStats, setPlayers]);

  // Input Handling
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // Initialize on mount or when switching to PLAYING
  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  // Game Loop
  const update = () => {
    if (gameState !== GameState.PLAYING) return;

    frameRef.current++;
    const canvas = canvasRef.current;
    if (!canvas) return;

    // --- Wave Management ---
    const enemies = entitiesRef.current.filter(e => e.type === 'enemy');
    const players = entitiesRef.current.filter(e => e.type === 'player' && !e.isDead);

    // Game Over Check
    if (players.length === 0) {
      setGameState(GameState.GAME_OVER);
      setStats({...statsRef.current});
      return;
    }

    // Spawn Logic
    const enemiesToSpawn = statsRef.current.wave * 2 + 1;
    const maxEnemies = 4 + statsRef.current.wave;

    // Simple wave logic: Keep spawning until killed count matches target for wave, but don't overwhelm
    // Actually simpler: Infinite scaling waves.
    if (enemies.length < Math.min(maxEnemies, statsRef.current.wave + 2) && frameRef.current % 120 === 0) {
      const side = Math.random() > 0.5 ? -50 : canvas.width + 50;
      entitiesRef.current.push({
        id: `enemy_${frameRef.current}`,
        type: 'enemy',
        pos: { x: side, y: GROUND_Y },
        vel: { x: 0, y: 0 },
        width: 30,
        height: 60,
        color: '#333',
        isGrounded: false,
        health: 40 + (statsRef.current.wave * 10),
        maxHealth: 40 + (statsRef.current.wave * 10),
        isDead: false,
        facingRight: side < canvas.width / 2,
        attackCooldown: 0,
        isAttacking: false,
        attackFrame: 0,
      });
    }

    // Next Wave Check (every 5 kills)
    if (statsRef.current.enemiesKilled > statsRef.current.wave * 5) {
        statsRef.current.wave++;
        // Heal players slightly
        entitiesRef.current.forEach(e => {
            if (e.type === 'player' && !e.isDead) {
                e.health = Math.min(e.health + 20, e.maxHealth);
            }
        });
    }

    statsRef.current.timeSurvived += 1/60;

    // --- Entity Update ---
    entitiesRef.current.forEach(entity => {
      if (entity.isDead) return;

      // Gravity
      entity.vel.y += GRAVITY;
      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // Friction
      entity.vel.x *= FRICTION;

      // Floor Collision
      if (entity.pos.y >= GROUND_Y) {
        entity.pos.y = GROUND_Y;
        entity.vel.y = 0;
        entity.isGrounded = true;
      } else {
        entity.isGrounded = false;
      }

      // Boundaries
      if (entity.pos.x < 0) entity.pos.x = 0;
      if (entity.pos.x > canvas.width) entity.pos.x = canvas.width;

      // Cooldowns
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 10) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      // -- Player Logic --
      if (entity.type === 'player') {
        const isP1 = entity.playerIndex === 0;
        const up = isP1 ? 'KeyW' : 'ArrowUp';
        const left = isP1 ? 'KeyA' : 'ArrowLeft';
        const right = isP1 ? 'KeyD' : 'ArrowRight';
        const attack = isP1 ? 'Space' : 'Enter';

        // Move
        if (keysRef.current.has(left)) {
          entity.vel.x -= MOVE_SPEED;
          entity.facingRight = false;
        }
        if (keysRef.current.has(right)) {
          entity.vel.x += MOVE_SPEED;
          entity.facingRight = true;
        }
        // Jump
        if (keysRef.current.has(up) && entity.isGrounded) {
          entity.vel.y = JUMP_FORCE;
        }
        // Attack
        if (keysRef.current.has(attack) && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;
          // Create hitbox
          const hitX = entity.facingRight ? entity.pos.x + 40 : entity.pos.x - 40;
          const hitbox = { x: hitX, y: entity.pos.y, radius: ATTACK_RANGE };

          // Check collisions with enemies
          entitiesRef.current.forEach(target => {
            if (target.type === 'enemy' && !target.isDead) {
                const dx = target.pos.x - hitbox.x;
                const dy = (target.pos.y - 30) - (hitbox.y - 30);
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < hitbox.radius) {
                    // HIT!
                    target.health -= ATTACK_DAMAGE;
                    target.vel.x = entity.facingRight ? 10 : -10; // Knockback
                    target.vel.y = -5;
                    spawnParticles(target.pos.x, target.pos.y - 30, target.color, 5);
                    if (target.health <= 0) {
                        target.isDead = true;
                        statsRef.current.score += 100;
                        statsRef.current.enemiesKilled++;
                        spawnParticles(target.pos.x, target.pos.y - 30, '#ff0000', 20); // Blood explosion
                    }
                }
            }
          });
        }
      }

      // -- Enemy AI --
      if (entity.type === 'enemy') {
        // Find nearest player
        let targetPlayer: Entity | null = null;
        let minDist = Infinity;

        entitiesRef.current.forEach(p => {
            if (p.type === 'player' && !p.isDead) {
                const dist = Math.abs(p.pos.x - entity.pos.x);
                if (dist < minDist) {
                    minDist = dist;
                    targetPlayer = p;
                }
            }
        });

        if (targetPlayer) {
            // Move towards
            if (targetPlayer.pos.x > entity.pos.x + 40) {
                entity.vel.x += MOVE_SPEED * 0.4; // Slower than player
                entity.facingRight = true;
            } else if (targetPlayer.pos.x < entity.pos.x - 40) {
                entity.vel.x -= MOVE_SPEED * 0.4;
                entity.facingRight = false;
            }

            // Attack logic
            const dist = Math.abs(targetPlayer.pos.x - entity.pos.x);
            if (dist < 60 && entity.attackCooldown === 0) {
                 entity.isAttacking = true;
                 entity.attackCooldown = ATTACK_COOLDOWN + 20; // Slower attacks

                 // Delayed hit (enemies wind up)
                 if (frameRef.current % 2 === 0) { // Simple hit check
                    targetPlayer.health -= 5 + statsRef.current.wave; // Scaling damage
                    targetPlayer.vel.x = entity.facingRight ? 5 : -5;
                    targetPlayer.vel.y = -2;
                    spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y - 30, '#ff0000', 3);
                    if (targetPlayer.health <= 0) {
                        targetPlayer.isDead = true;
                        spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y, targetPlayer.color, 30);
                    }
                 }
            }
        }
      }
    });

    // Cleanup Dead Entities (Keep players to show dead body, remove enemies)
    entitiesRef.current = entitiesRef.current.filter(e => e.type === 'player' || !e.isDead || (e.isDead && Math.random() > 0.95)); // Fade out enemies slowly logic replaced by filter for now to keep simple

    // Particles Update
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += 0.5; // Gravity
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    // Sync UI mostly every frame is fine for local state, but let's throttle slightly if needed.
    // Here we just set it every frame because React handles diffing.
    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  };

  const spawnParticles = (x: number, y: number, color: string, count: number) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * 10, y: (Math.random() - 0.5) * 10 },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 4 + 1
          });
      }
  };

  // Draw Loop
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Floor
    ctx.fillStyle = '#222';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    ctx.strokeStyle = '#444';
    ctx.beginPath();
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // Draw Particles
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    // Draw Entities
    entitiesRef.current.forEach(entity => {
      if (entity.isDead && entity.type === 'enemy') return; // Don't draw dead enemies (they pop)

      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);
      if (!entity.facingRight) ctx.scale(-1, 1); // Flip horizontally

      // Color
      ctx.strokeStyle = entity.isDead ? '#555' : entity.color;
      ctx.fillStyle = entity.isDead ? '#555' : entity.color;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // --- Stickman Drawing ---

      // Animation States
      const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
      const runAnim = isRunning ? Math.sin(frameRef.current * 0.4) * 10 : 0;
      const isAttacking = entity.isAttacking;

      // 1. Legs
      // Hip point is (0, -30) relative to feet (0,0)
      const hipX = 0;
      const hipY = -30;

      ctx.beginPath();
      // Left Leg
      ctx.moveTo(hipX, hipY);
      ctx.lineTo(-10 + runAnim, 0); // Foot
      // Right Leg
      ctx.moveTo(hipX, hipY);
      ctx.lineTo(10 - runAnim, 0); // Foot
      ctx.stroke();

      // 2. Body
      ctx.beginPath();
      ctx.moveTo(hipX, hipY);
      ctx.lineTo(0, -60); // Neck
      ctx.stroke();

      // 3. Head
      ctx.beginPath();
      ctx.arc(0, -70, 10, 0, Math.PI * 2); 
      if (entity.type === 'enemy') {
          // Red eye for enemies
          ctx.fillStyle = '#000';
          ctx.fill();
          ctx.strokeStyle = '#fff'; // White outline for contrast
          ctx.stroke();
          ctx.fillStyle = 'red';
          ctx.beginPath();
          ctx.arc(4, -70, 3, 0, Math.PI * 2);
          ctx.fill();
      } else {
          ctx.fill(); // Solid head color
      }

      // 4. Arms
      ctx.beginPath();
      ctx.strokeStyle = entity.isDead ? '#555' : entity.color; // Reset stroke
      const shoulderY = -55;

      if (isAttacking) {
          // Attack Pose (Punch/Swing)
          const attackReach = 15 + (entity.attackFrame * 2); // Extend arm
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(attackReach, shoulderY); 
          // Sword/Weapon visual effect
           ctx.shadowBlur = 10;
           ctx.shadowColor = entity.color;
           ctx.lineTo(attackReach + 20, shoulderY);
           ctx.shadowBlur = 0;
      } else {
          // Idle/Run Arms
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-15 - runAnim, shoulderY + 15);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(15 + runAnim, shoulderY + 15);
      }
      ctx.stroke();

      // Health bar above head ( Enemies only, UI handles players)
      if (entity.type === 'enemy') {
          ctx.restore(); // Undo flip for text
          ctx.save();
          ctx.translate(entity.pos.x, entity.pos.y - 90);
          ctx.fillStyle = 'red';
          ctx.fillRect(-15, 0, 30, 4);
          ctx.fillStyle = '#0f0';
          ctx.fillRect(-15, 0, 30 * (entity.health / entity.maxHealth), 4);
      }

      ctx.restore();
    });
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    // Setup Canvas
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }

    // Start Loop
    requestRef.current = requestAnimationFrame(tick);

    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gameState]); // Restart loop if state changes fundamentally

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-neutral-900"
    />
  );
};

export default GameCanvas;

