import React, { useRef, useEffect, useState } from 'react';
import { PlanetData, Star, ViewMode } from '../types';

interface SolarCanvasProps {
  planets: PlanetData[];
  selectedPlanet: PlanetData | null;
  onPlanetSelect: (p: PlanetData | null) => void;
}

const SolarCanvas: React.FC<SolarCanvasProps> = ({ planets, selectedPlanet, onPlanetSelect }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef<number>(0);
  const starsRef = useRef<Star[]>([]);
  const animationRef = useRef<number>();

  // Track orbit angles locally for smooth animation
  const anglesRef = useRef<{[key: string]: number}>({});

  // Initialize Stars
  useEffect(() => {
    const stars: Star[] = [];
    for (let i = 0; i < 300; i++) {
      stars.push({
        x: Math.random() * window.innerWidth,
        y: Math.random() * window.innerHeight,
        size: Math.random() * 2,
        opacity: Math.random(),
        twinkleSpeed: 0.005 + Math.random() * 0.02
      });
    }
    starsRef.current = stars;

    // Init angles
    planets.forEach(p => {
      if (anglesRef.current[p.id] === undefined) {
        anglesRef.current[p.id] = Math.random() * Math.PI * 2;
      }
    });
  }, [planets]);

  // Click Handler
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const handleClick = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;

      // Check clicks (accounting for translation if needed, but we keep it simple first)
      // We need to calculate where planets are currently drawn to detect click
      let clicked = null;

      // If a planet is selected, we might want to click "off" to deselect
      // But let's check planet positions first
      // Note: This duplicates logic from draw(), ideally shared, but kept simple here
      const scale = selectedPlanet ? 0.8 : 1; // Visual scale matches draw
      // In focus mode, logic is different. For simplicity, click detection works best in Orbit view.

      if (!selectedPlanet) {
        for (const p of planets) {
            const angle = anglesRef.current[p.id];
            const px = centerX + Math.cos(angle) * p.distance * scale;
            const py = centerY + Math.sin(angle) * p.distance * scale;
            const dist = Math.sqrt(Math.pow(x - px, 2) + Math.pow(y - py, 2));

            // Hitbox slightly larger than planet
            if (dist < p.radius + 15) {
                clicked = p;
                break;
            }
        }
        onPlanetSelect(clicked); // clicked can be null (deselect) or planet
      } else {
        // If focused, clicking mostly deselects unless we add UI to close
        // We defer close logic to UI overlay
      }
    };

    canvas.addEventListener('click', handleClick);
    return () => canvas.removeEventListener('click', handleClick);
  }, [planets, selectedPlanet, onPlanetSelect]);

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    frameRef.current++;

    // Resize
    if (canvas.width !== window.innerWidth || canvas.height !== window.innerHeight) {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    }

    const w = canvas.width;
    const h = canvas.height;
    const centerX = w / 2;
    const centerY = h / 2;

    // Clear Background
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, w, h);

    // Draw Stars
    starsRef.current.forEach(star => {
      star.opacity += star.twinkleSpeed;
      if (star.opacity > 1 || star.opacity < 0.2) star.twinkleSpeed *= -1;

      ctx.globalAlpha = star.opacity;
      ctx.fillStyle = 'white';
      ctx.beginPath();
      ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.globalAlpha = 1;

    // Camera/View Transform
    ctx.save();

    if (selectedPlanet) {
        // Focus Mode: Move chosen planet to somewhat center-left
        // This is a simple visual trick: We don't actually move the camera to the planet in 3D space,
        // We just render a "Details View" of the planet.

        // Draw the planet large in the center-right
        const p = selectedPlanet;
        const renderX = w * 0.65;
        const renderY = centerY;
        const size = Math.min(w, h) * 0.35; // Big size

        // Atmosphere Glow
        const gradient = ctx.createRadialGradient(renderX, renderY, size * 0.8, renderX, renderY, size * 1.2);
        gradient.addColorStop(0, p.color);
        gradient.addColorStop(1, 'transparent');
        ctx.fillStyle = gradient;
        ctx.globalAlpha = 0.3;
        ctx.beginPath();
        ctx.arc(renderX, renderY, size * 1.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;

        // Planet Body
        drawPlanetBody(ctx, p, renderX, renderY, size);

    } else {
        // Orbit Mode
        const scale = 1;

        // Draw Sun
        const sunGrad = ctx.createRadialGradient(centerX, centerY, 10, centerX, centerY, 60);
        sunGrad.addColorStop(0, '#fff');
        sunGrad.addColorStop(0.2, '#fcd34d'); // Yellow-400
        sunGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = sunGrad;
        ctx.beginPath();
        ctx.arc(centerX, centerY, 60, 0, Math.PI * 2);
        ctx.fill();

        // Draw Orbits & Planets
        planets.forEach(p => {
             // Update position
             if (!selectedPlanet) {
                anglesRef.current[p.id] += p.speed;
             }
             const angle = anglesRef.current[p.id];
             const r = p.distance * scale;

             // Draw Orbit Line
             ctx.beginPath();
             ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
             ctx.lineWidth = 1;
             ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
             ctx.stroke();

             // Position
             const px = centerX + Math.cos(angle) * r;
             const py = centerY + Math.sin(angle) * r;

             // Draw Planet
             drawPlanetBody(ctx, p, px, py, p.radius);

             // Label (only if mouse hover roughly? or always)
             ctx.fillStyle = 'white';
             ctx.font = '10px Exo 2';
             ctx.textAlign = 'center';
             ctx.fillText(p.name, px, py + p.radius + 15);
        });
    }

    ctx.restore();
    animationRef.current = requestAnimationFrame(draw);
  };

  const drawPlanetBody = (ctx: CanvasRenderingContext2D, p: PlanetData, x: number, y: number, r: number) => {
    ctx.save();

    // Rings (Back)
    if (p.textureType === 'ringed') {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(Math.PI / 6);
        ctx.beginPath();
        ctx.strokeStyle = 'rgba(200, 180, 150, 0.6)';
        ctx.lineWidth = r * 0.4;
        ctx.ellipse(0, 0, r * 2.2, r * 0.8, 0, Math.PI, 0); // Back half
        ctx.stroke();
        ctx.restore();
    }

    // Main Sphere
    const grad = ctx.createRadialGradient(x - r/3, y - r/3, r/10, x, y, r);
    if (p.gradientColors && p.gradientColors.length > 1) {
        grad.addColorStop(0, p.gradientColors[0]);
        grad.addColorStop(1, p.gradientColors[1]);
    } else {
        grad.addColorStop(0, p.color);
        grad.addColorStop(1, 'black');
    }

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();

    // Stripes (Jupiter style)
    if (p.textureType === 'striped') {
        ctx.save();
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.clip(); // Clip stripes to planet circle

        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#5c4033'; // Dark band
        ctx.fillRect(x - r, y - r * 0.5, r * 2, r * 0.2);
        ctx.fillRect(x - r, y + r * 0.2, r * 2, r * 0.15);
        ctx.restore();
    }

    // Earth-like continents (blobs)
    if (p.name === 'Earth') {
        ctx.save();
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.clip();

        ctx.fillStyle = '#4ade80'; // Green
        ctx.globalAlpha = 0.6;
        // Simple random looking blobs based on hardcoded offsets
        ctx.beginPath();
        ctx.arc(x - r*0.4, y - r*0.3, r*0.4, 0, Math.PI*2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(x + r*0.5, y + r*0.2, r*0.5, 0, Math.PI*2);
        ctx.fill();
        ctx.restore();
    }

    // Rings (Front)
    if (p.textureType === 'ringed') {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(Math.PI / 6);
        ctx.beginPath();
        ctx.strokeStyle = 'rgba(200, 180, 150, 0.8)'; // Brighter front
        ctx.lineWidth = r * 0.4;
        ctx.ellipse(0, 0, r * 2.2, r * 0.8, 0, 0, Math.PI); // Front half
        ctx.stroke();
        ctx.restore();
    }

    // Shadow (Night side) for 3D effect
    const shadowGrad = ctx.createRadialGradient(x, y, r * 0.8, x + r*0.5, y + r*0.5, r * 1.5);
    shadowGrad.addColorStop(0, 'transparent');
    shadowGrad.addColorStop(1, 'rgba(0,0,0,0.8)');
    ctx.fillStyle = shadowGrad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  };

  useEffect(() => {
    animationRef.current = requestAnimationFrame(draw);
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }); // Run every render to catch prop updates

  return <canvas ref={canvasRef} className="block w-full h-full" />;
};

export default SolarCanvas;

