import React, { useState, useRef, useEffect } from 'react';
import { PlanetData, ChatMessage } from '../types';
import { askCaptainNova } from '../services/geminiService';

interface PlanetOverlayProps {
  planet: PlanetData | null;
  onClose: () => void;
}

const PlanetOverlay: React.FC<PlanetOverlayProps> = ({ planet, onClose }) => {
  const [chatInput, setChatInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // 切换星球时的欢迎语
  useEffect(() => {
    if (planet) {
        setMessages([
            { role: 'model', text: `欢迎来到${planet.name}！🌟 我是 Nova 队长。关于这个星球，你想知道什么？` }
        ]);
    }
  }, [planet]);

  // 自动滚动聊天记录
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !planet) return;

    const userText = chatInput;
    setChatInput('');
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setIsLoading(true);

    const answer = await askCaptainNova(planet.name, userText);

    setIsLoading(false);
    setMessages(prev => [...prev, { role: 'model', text: answer }]);
  };

  if (!planet) {
    return (
        <div className="absolute top-8 left-1/2 -translate-x-1/2 pointer-events-none text-center animate-bounce z-40">
            <p className="text-blue-300 text-lg text-shadow-lg font-mono bg-black/50 px-6 py-2 rounded-full border border-blue-500/30 backdrop-blur-sm">
                👆 点击行星开始探索！
            </p>
        </div>
    );
