const createClient = () => {
  const apiKey = process.env.API_KEY || '';
  if (!apiKey) {
    console.warn("未找到 API Key");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

export const askCaptainNova = async (planetName: string, question: string): Promise<string> => {
  const client = createClient();
  if (!client) return "通讯链路中断！(请检查 API Key)";

  try {
    const prompt = `
      你是一个名叫 Nova 队长 👨‍🚀 的宇航员，正在为中小学生（8-12岁）科普太阳系知识。

      当前所在的星球：${planetName}
      小朋友的问题："${question}"

      规则：
      1. 用**中文**回答。
      2. 保持回答简短（不超过3句话）。
      3. 语言生动有趣，充满好奇心。
      4. 适当使用 1-2 个表情符号 🌟。
      5. 确保科学知识准确（基于 NASA 数据），但要通俗易懂。

      请直接回答问题。
    `;

    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "信号受到干扰... 请再说一遍，小学员！";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "休斯顿，我们遇到问题了！(连接错误)";
  }
};

export const getTacticalAnalysis = async (stats: GameStats): Promise<string> => {
  const client = createClient();
  if (!client) return "Tactical link offline.";

  try {
    const prompt = `
      Analyze the following space mission stats:
      Score: ${stats.score}
      Wave Reached: ${stats.wave}
      Enemies Defeated: ${stats.enemiesKilled}

      Provide a 1-sentence tactical analysis in a sci-fi commander style.
    `;

    const response = await client.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "Analysis complete.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Data corruption detected.";
  }
};

