            >
              🔄 重新挑战
            </button>
            <button
              onClick={onMenu}
              className="px-10 py-4 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg transition-all transform hover:scale-105 shadow-lg text-lg"
            >
              🏠 返回主菜单
