          </div>
        </div>
      </div>
    </div>
  );
};

export default GameOver;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats } from '../types';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  playerCount: number;
}

// 物理常量
const GRAVITY = 0.8;
const FRICTION = 0.85;
const MOVE_SPEED = 1.2;
const JUMP_FORCE = -17;
const GROUND_Y = 550; // 地面高度
const ATTACK_COOLDOWN = 25; // 攻击冷却帧数
const ATTACK_RANGE = 75;
const ATTACK_DAMAGE = 35;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, playerCount }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  // 使用 Ref 存储高频变化的游戏状态，避免 React 渲染开销
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 });

  // 屏幕震动
  const shakeRef = useRef<number>(0);

  // 初始化游戏
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // 玩家 1 (蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 30, height: 60, color: '#3b82f6', // blue-500
      isGrounded: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // 玩家 2 (橙)
    if (playerCount === 2) {
      newEntities.push({
        id: 'p2', type: 'player', playerIndex: 1,
        pos: { x: 300, y: GROUND_Y }, vel: { x: 0, y: 0 },
        width: 30, height: 60, color: '#f97316', // orange-500
        isGrounded: false, health: 100, maxHealth: 100, isDead: false,
        facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      });
    }

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  }, [playerCount, setStats, setPlayers]);

  // 键盘监听
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  // 粒子生成器
  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 10) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2
          });
      }
  };

  // 主更新循环
  const update = () => {
    if (gameState !== GameState.PLAYING) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;

    // --- 游戏逻辑 ---
    const enemies = entitiesRef.current.filter(e => e.type === 'enemy');
    const players = entitiesRef.current.filter(e => e.type === 'player' && !e.isDead);

    // 失败判定：所有玩家阵亡
    if (players.length === 0) {
      // 延迟一点再显示结束，以免太突然
      if (entitiesRef.current.some(e => e.type === 'player')) {
          // 还有玩家尸体没清理（逻辑上 players 过滤掉了 dead），这里简单直接判定
           setGameState(GameState.GAME_OVER);
           setStats({...statsRef.current});
           return;
      }
    }

    // 敌人生成逻辑 (波次难度递增)
    const maxEnemies = 3 + Math.floor(statsRef.current.wave * 1.5); // 每波敌人上限增加
    const spawnRate = Math.max(30, 120 - statsRef.current.wave * 5); // 生成速度变快

    if (enemies.length < maxEnemies && frameRef.current % spawnRate === 0) {
      const side = Math.random() > 0.5 ? -60 : canvas.width + 60;
      const hp = 50 + (statsRef.current.wave * 15); // 血量随波次增加
      entitiesRef.current.push({
        id: `enemy_${frameRef.current}`,
        type: 'enemy',
        pos: { x: side, y: GROUND_Y },
        vel: { x: 0, y: 0 },
        width: 30, height: 60, color: '#ef4444', // Red enemies
        isGrounded: false, health: hp, maxHealth: hp, isDead: false,
        facingRight: side < canvas.width / 2,
        attackCooldown: 0, isAttacking: false, attackFrame: 0,
      });
    }

    // 波次升级：每击杀 5 个敌人升一波
    if (statsRef.current.enemiesKilled > 0 && statsRef.current.enemiesKilled % 5 === 0 && statsRef.current.wave <= statsRef.current.enemiesKilled / 5) {
        statsRef.current.wave++;
        // 升级回血奖励
        entitiesRef.current.forEach(e => {
            if (e.type === 'player' && !e.isDead) {
                e.health = Math.min(e.health + 25, e.maxHealth);
                spawnParticles(e.pos.x, e.pos.y - 40, '#00ff00', 10, 5); // 治疗特效
            }
        });
    }

    statsRef.current.timeSurvived += 1/60;

    // --- 实体物理与行为 ---
    entitiesRef.current.forEach(entity => {
      if (entity.isDead) return;

      // 重力与移动
      entity.vel.y += GRAVITY;
      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;
      entity.vel.x *= FRICTION; // 地面摩擦

      // 地面碰撞
      if (entity.pos.y >= GROUND_Y) {
        entity.pos.y = GROUND_Y;
        entity.vel.y = 0;
        entity.isGrounded = true;
      } else {
        entity.isGrounded = false;
      }

      // 边界限制
      if (entity.pos.x < 15) entity.pos.x = 15;
      if (entity.pos.x > canvas.width - 15) entity.pos.x = canvas.width - 15;

      // 攻击冷却
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 12) { // 攻击动画时长
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      // --- 玩家操作 ---
      if (entity.type === 'player') {
        const isP1 = entity.playerIndex === 0;
        const up = isP1 ? 'KeyW' : 'ArrowUp';
        const left = isP1 ? 'KeyA' : 'ArrowLeft';
        const right = isP1 ? 'KeyD' : 'ArrowRight';
        const attack = isP1 ? 'Space' : 'Enter';

        if (keysRef.current.has(left)) {
          entity.vel.x -= MOVE_SPEED;
          entity.facingRight = false;
        }
        if (keysRef.current.has(right)) {
          entity.vel.x += MOVE_SPEED;
          entity.facingRight = true;
        }
        if (keysRef.current.has(up) && entity.isGrounded) {
          entity.vel.y = JUMP_FORCE;
        }

        // 攻击逻辑
        if (keysRef.current.has(attack) && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;

          // 判定攻击
          const hitX = entity.facingRight ? entity.pos.x + 50 : entity.pos.x - 50;
          const hitRadius = ATTACK_RANGE;
          let hitCount = 0;

          entitiesRef.current.forEach(target => {
            if (target.type === 'enemy' && !target.isDead) {
                const dx = target.pos.x - hitX;
                const dy = (target.pos.y - 30) - (entity.pos.y - 30);
                if (Math.sqrt(dx*dx + dy*dy) < hitRadius) {
                    // 命中!
                    target.health -= ATTACK_DAMAGE;
                    target.vel.x = entity.facingRight ? 15 : -15; // 击退
                    target.vel.y = -8; // 浮空
                    shakeRef.current = 5; // 震屏
                    hitCount++;

                    spawnParticles(target.pos.x, target.pos.y - 30, '#fff', 5); // 打击火花

                    if (target.health <= 0) {
                        target.isDead = true;
                        statsRef.current.score += 100 * statsRef.current.wave;
                        statsRef.current.enemiesKilled++;
                        spawnParticles(target.pos.x, target.pos.y - 30, target.color, 25); // 死亡爆炸
                    }
                }
            }
          });
        }
      }

      // --- 敌人 AI ---
      if (entity.type === 'enemy') {
        // 寻找最近的存活玩家
        let targetPlayer: Entity | null = null;
        let minDist = Infinity;

        entitiesRef.current.forEach(p => {
            if (p.type === 'player' && !p.isDead) {
                const dist = Math.abs(p.pos.x - entity.pos.x);
                if (dist < minDist) {
                    minDist = dist;
                    targetPlayer = p;
                }
            }
        });

        if (targetPlayer) {
            // 移动AI
            if (targetPlayer.pos.x > entity.pos.x + 40) {
                entity.vel.x += MOVE_SPEED * 0.5;
                entity.facingRight = true;
            } else if (targetPlayer.pos.x < entity.pos.x - 40) {
                entity.vel.x -= MOVE_SPEED * 0.5;
                entity.facingRight = false;
            }

            // 攻击AI
            const dist = Math.abs(targetPlayer.pos.x - entity.pos.x);
            if (dist < 60 && entity.attackCooldown === 0) {
                 entity.isAttacking = true;
                 entity.attackCooldown = ATTACK_COOLDOWN + 30; // 敌人攻击频率慢

                 // 延迟伤害判定 (模拟前摇)
                 if (frameRef.current % 5 === 0) {
                    targetPlayer.health -= 8 + statsRef.current.wave; 
                    targetPlayer.vel.x = entity.facingRight ? 8 : -8;
                    targetPlayer.vel.y = -4;
                    spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y - 30, '#ff0000', 5);
                    shakeRef.current = 3;

                    if (targetPlayer.health <= 0) {
                        targetPlayer.isDead = true;
                        spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y, targetPlayer.color, 40);
                    }
                 }
            }
        }
      }
    });

    // 清理死亡单位（保留玩家尸体以示悲壮，移除敌人）
    entitiesRef.current = entitiesRef.current.filter(e => e.type === 'player' || !e.isDead);

    // 更新粒子
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += 0.5; // 粒子重力
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    // 同步UI数据
    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  };

  // 渲染循环
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清屏
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 震屏偏移
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景装饰
    ctx.fillStyle = '#222';
    // 简单的远景楼宇剪影
    ctx.fillRect(100, GROUND_Y - 200, 100, 200);
    ctx.fillRect(300, GROUND_Y - 300, 150, 300);
    ctx.fillRect(600, GROUND_Y - 150, 80, 150);
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    // 地面线
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // 绘制粒子
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    // 绘制实体
    entitiesRef.current.forEach(entity => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);
      if (!entity.facingRight) ctx.scale(-1, 1);

      // 颜色设定
      const color = entity.isDead ? '#555' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // --- 火柴人骨骼绘制 ---

      const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
      const runCycle = Math.sin(frameRef.current * 0.5) * 15;
      const runOffset = isRunning ? runCycle : 0;

      const hipY = -35;
      const headY = -75;

      // 腿
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(-10 + runOffset, 0); // 后脚
      ctx.moveTo(0, hipY);
      ctx.lineTo(10 - runOffset, 0); // 前脚
      ctx.stroke();

      // 躯干
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(0, headY + 10);
      ctx.stroke();

      // 头
      ctx.beginPath();
      ctx.arc(0, headY, 12, 0, Math.PI * 2);
      ctx.fill();

      // 手臂
      ctx.beginPath();
      const shoulderY = -65;

      if (entity.isAttacking) {
          // 攻击姿态：向前猛击
          const punchExtend = 15 + (entity.attackFrame * 3);
          // 后手
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-10, shoulderY + 10);
          // 前手 (攻击手)
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(punchExtend, shoulderY);

          // 武器/拳风特效
          ctx.save();
          ctx.shadowBlur = 15;
          ctx.shadowColor = entity.color;
          ctx.fillStyle = '#fff';
          ctx.fillRect(punchExtend, shoulderY - 5, 20, 10); // 简单的拳头/刀光
          ctx.restore();
      } else {
          // 正常姿态
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-15 - runOffset, shoulderY + 15);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(15 + runOffset, shoulderY + 15);
      }
      ctx.stroke();

      // 敌人血条 (头顶)
      if (entity.type === 'enemy' && !entity.isDead) {
          ctx.restore(); // 暂时取消翻转
          ctx.save();
          ctx.translate(entity.pos.x, entity.pos.y - 100);
          ctx.fillStyle = 'red';
          ctx.fillRect(-20, 0, 40, 4);
          ctx.fillStyle = '#0f0';
          ctx.fillRect(-20, 0, 40 * (entity.health / entity.maxHealth), 4);
      }

      ctx.restore();
    });

    ctx.restore(); // End shake
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    // Canvas 自适应
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-neutral-900"
    />
  );
};

export default GameCanvas;

import React, { useState } from 'react';
import GameCanvas from './components/GameCanvas';
import GameUI from './components/GameUI';
import MainMenu from './components/MainMenu';
import GameOver from './components/GameOver';
import { GameState, GameStats, Entity } from './types';

function App() {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [playerCount, setPlayerCount] = useState<1 | 2>(1);
  const [stats, setStats] = useState<GameStats>({ score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 });
  const [players, setPlayers] = useState<Entity[]>([]);

  const handleRestart = () => {
    setGameState(GameState.PLAYING);
  };

  const handleMenu = () => {
    setGameState(GameState.MENU);
  };

  return (
    <div className="relative w-screen h-screen bg-gray-900 overflow-hidden">
      {/* 游戏渲染层 */}
      <div className="absolute inset-0 z-10">
        <GameCanvas 
          gameState={gameState} 
          setGameState={setGameState}
          setStats={setStats}
          setPlayers={setPlayers}
          playerCount={playerCount}
        />
      </div>

      {/* 游戏 UI 层 (Playing 状态可见) */}
      {gameState === GameState.PLAYING && (
        <div className="absolute inset-0 z-20 pointer-events-none">
          <GameUI stats={stats} players={players} />
        </div>
      )}

      {/* 菜单层 */}
      {gameState === GameState.MENU && (
        <MainMenu setGameState={setGameState} setPlayerCount={setPlayerCount} />
      )}

      {/* 游戏结束层 */}
      {gameState === GameState.GAME_OVER && (
        <GameOver 
          stats={stats} 
          onRestart={handleRestart} 
          onMenu={handleMenu}
        />
      )}
    </div>
  );
}

export default App;

export enum GameState {
  MENU,
  PLAYING,
  SKILL_MENU, // 新增：技能菜单状态
  GAME_OVER,
  PAUSED
}

export interface Vector {
  x: number;
  y: number;
}

export type SkillType = 'FIREBALL' | 'HEAL' | 'RAGE';

export interface SkillDef {
  id: SkillType;
  name: string;
  desc: string;
  baseCooldown: number; // frames
  cost: number; // SP cost
  maxLevel: number;
}

export interface PlayerSkills {
  points: number;
  levels: Record<SkillType, number>;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number; 
  type: 'player' | 'enemy' | 'projectile'; // 新增 projectile
  playerIndex?: number; 

  // 技能相关
  skillCooldowns: Record<SkillType, number>;
  rageDuration: number; // 狂暴剩余时间
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
}

export interface GameStats {
  score: number;
  wave: number;
  enemiesKilled: number;
  timeSurvived: number;
}

import React from 'react';
import { GameState, PlayerSkills, SkillDef, SkillType } from '../types';

export const SKILL_DEFINITIONS: Record<SkillType, SkillDef> = {
  FIREBALL: {
    id: 'FIREBALL',
    name: '火球术',
    desc: '发射一枚高爆火球，造成远程伤害。',
    baseCooldown: 120, // 2秒
    cost: 1,
    maxLevel: 5
  },
  HEAL: {
    id: 'HEAL',
    name: '战地急救',
    desc: '立即恢复部分生命值。',
    baseCooldown: 600, // 10秒
    cost: 2,
    maxLevel: 3
  },
  RAGE: {
    id: 'RAGE',
    name: '狂暴模式',
    desc: '短时间内提升移速和攻击力。',
    baseCooldown: 900, // 15秒
    cost: 3,
    maxLevel: 3
  }
};

interface SkillMenuProps {
  playerSkills: PlayerSkills[];
  setPlayerSkills: React.Dispatch<React.SetStateAction<PlayerSkills[]>>;
  onNextWave: () => void;
  playerCount: number;
}

const SkillMenu: React.FC<SkillMenuProps> = ({ playerSkills, setPlayerSkills, onNextWave, playerCount }) => {

  const upgradeSkill = (playerIdx: number, skillId: SkillType) => {
    const skills = [...playerSkills];
    const player = skills[playerIdx];
    const def = SKILL_DEFINITIONS[skillId];

    if (player.points >= def.cost && player.levels[skillId] < def.maxLevel) {
      player.points -= def.cost;
      player.levels[skillId]++;
      setPlayerSkills(skills);
    }
  };

  return (
    <div className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-black/95 backdrop-blur-md">
      <h2 className="text-5xl font-comic text-yellow-400 mb-2 animate-bounce">
        战场补给站
      </h2>
      <p className="text-gray-400 mb-8 font-mono">下一波敌军即将抵达，请强化装备！</p>

      <div className="flex gap-8 w-full max-w-6xl px-8 justify-center">
        {[0, 1].map((pIdx) => {
          if (pIdx === 1 && playerCount < 2) return null;
          const skills = playerSkills[pIdx];
          const color = pIdx === 0 ? 'border-blue-500' : 'border-orange-500';
          const title = pIdx === 0 ? '玩家 1 (WASD)' : '玩家 2 (方向键)';
          const textCol = pIdx === 0 ? 'text-blue-400' : 'text-orange-400';

          return (
            <div key={pIdx} className={`flex-1 bg-gray-900 border-2 ${color} rounded-xl p-6 relative`}>
              <div className="flex justify-between items-center mb-6 border-b border-gray-700 pb-4">
                <h3 className={`text-2xl font-bold ${textCol}`}>{title}</h3>
                <div className="bg-yellow-600/20 text-yellow-400 px-4 py-2 rounded-full font-mono border border-yellow-500/50">
                  技能点: {skills.points}
                </div>
              </div>

              <div className="space-y-4">
                {(Object.keys(SKILL_DEFINITIONS) as SkillType[]).map((skillId) => {
                  const def = SKILL_DEFINITIONS[skillId];
                  const level = skills.levels[skillId];
                  const canAfford = skills.points >= def.cost;
                  const isMax = level >= def.maxLevel;

                  return (
                    <div key={skillId} className="bg-gray-800 p-4 rounded-lg border border-gray-700 hover:border-gray-500 transition-colors flex items-center justify-between">
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="font-bold text-lg text-white">{def.name}</span>
                          <span className="text-xs bg-gray-700 px-2 py-0.5 rounded text-gray-300">Lv.{level}</span>
                        </div>
                        <div className="text-xs text-gray-400 mt-1">{def.desc}</div>
                        <div className="text-xs text-gray-500 mt-1">
                          按键: {pIdx === 0 ? (skillId === 'RAGE' ? 'E' : 'Q') : (skillId === 'RAGE' ? 'R-Ctrl' : 'R-Shift')} 
                          {skillId === 'HEAL' && ' (与Rage共用键位槽)'} 
                          {/* 简化：我们把 Fireball 绑在 Slot 1, Heal/Rage 绑在 Slot 2 */}
                        </div>
                      </div>

                      <button
                        onClick={() => upgradeSkill(pIdx, skillId)}
                        disabled={!canAfford || isMax}
                        className={`px-4 py-2 rounded font-bold text-sm transition-all ${
                          isMax 
                            ? 'bg-green-900 text-green-400 cursor-default'
                            : canAfford 
                              ? 'bg-yellow-600 hover:bg-yellow-500 text-white shadow-lg hover:scale-105' 
                              : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                        }`}
                      >
                        {isMax ? '已满级' : `升级 (-${def.cost} SP)`}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      <button
        onClick={onNextWave}
        className="mt-12 px-12 py-4 bg-gradient-to-r from-red-600 to-red-500 text-white text-2xl font-bold rounded-lg hover:scale-105 transition-transform shadow-[0_0_30px_rgba(220,38,38,0.5)] font-comic"
      >
        >>> 开始下一波 >>>
      </button>
    </div>
  );
};

export default SkillMenu;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, PlayerSkills, SkillType } from '../types';
import { SKILL_DEFINITIONS } from './SkillMenu';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  playerCount: number;
  playerSkills: PlayerSkills[]; // 来自 App 的技能状态
  onWaveComplete: () => void;   // 通知 App 增加技能点
}

// 物理常量
const GRAVITY = 0.8;
const FRICTION = 0.85;
const MOVE_SPEED = 1.2;
const JUMP_FORCE = -17;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 25;
const ATTACK_RANGE = 75;
const ATTACK_DAMAGE = 35;

const GameCanvas: React.FC<GameCanvasProps> = ({ 
    gameState, setGameState, setStats, setPlayers, playerCount, playerSkills, onWaveComplete 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 });
  const shakeRef = useRef<number>(0);

  // 波次管理
  const waveStateRef = useRef({
      enemiesSpawned: 0,
      maxEnemies: 0,
      waveInProgress: false
  });

  // 初始化游戏
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // 创建玩家
    for(let i=0; i<playerCount; i++) {
        newEntities.push({
            id: `p${i+1}`, type: 'player', playerIndex: i,
            pos: { x: 200 + i * 100, y: GROUND_Y }, vel: { x: 0, y: 0 },
            width: 30, height: 60, color: i === 0 ? '#3b82f6' : '#f97316',
            isGrounded: false, health: 100, maxHealth: 100, isDead: false,
            facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
            skillCooldowns: { FIREBALL: 0, HEAL: 0, RAGE: 0 },
            rageDuration: 0
        });
    }

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { score: 0, wave: 1, enemiesKilled: 0, timeSurvived: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    // 初始化第一波
    startWave(1);

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  }, [playerCount, setStats, setPlayers]);

  const startWave = (waveNum: number) => {
      waveStateRef.current = {
          enemiesSpawned: 0,
          maxEnemies: 4 + Math.floor(waveNum * 2.5), // 敌人数量随波次增加
          waveInProgress: true
      };
      statsRef.current.wave = waveNum;
  };

  // 键盘监听
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  // 状态切换处理
  useEffect(() => {
    if (gameState === GameState.PLAYING && frameRef.current === 0) {
      initGame();
    }
    // 如果从技能菜单回来，不需要重置，只需要继续循环
    if (gameState === GameState.PLAYING && !requestRef.current) {
        // start loop logic is handled by restart/init or resume
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 10) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2
          });
      }
  };

  // 使用技能逻辑
  const useSkill = (entity: Entity, skillType: SkillType) => {
      const pSkills = playerSkills[entity.playerIndex!];
      const level = pSkills.levels[skillType];

      if (level === 0) return; // 未学习
      if (entity.skillCooldowns[skillType] > 0) return; // 冷却中

      const def = SKILL_DEFINITIONS[skillType];
      // 冷却时间随等级略微减少
      const cooldown = Math.max(30, def.baseCooldown - (level - 1) * 10);

      entity.skillCooldowns[skillType] = cooldown;

      // 技能效果
      if (skillType === 'FIREBALL') {
          const dir = entity.facingRight ? 1 : -1;
          entitiesRef.current.push({
              id: `proj_${Math.random()}`,
              type: 'projectile',
              pos: { x: entity.pos.x + dir * 40, y: entity.pos.y - 40 },
              vel: { x: dir * 15, y: 0 },
              width: 20, height: 20, color: '#f59e0b',
              isGrounded: false, health: 1, maxHealth: 1, isDead: false,
              facingRight: entity.facingRight, attackCooldown: 0, isAttacking: false, attackFrame: 0,
              skillCooldowns: { FIREBALL: 0, HEAL: 0, RAGE: 0 }, rageDuration: 0,
              // Projectile specific: store damage in 'health' or create new prop? 
              // reusing maxHealth as damage for projectile
              maxHealth: 40 + (level * 20) // Damage
          });
          spawnParticles(entity.pos.x + dir * 40, entity.pos.y - 40, '#f59e0b', 10);
      } else if (skillType === 'HEAL') {
          const healAmount = 30 + (level * 20);
          entity.health = Math.min(entity.health + healAmount, entity.maxHealth);
          spawnParticles(entity.pos.x, entity.pos.y - 30, '#10b981', 20, 3);
      } else if (skillType === 'RAGE') {
          entity.rageDuration = 300 + (level * 60); // 持续 5-8秒
          spawnParticles(entity.pos.x, entity.pos.y, '#ef4444', 30, 8);
          shakeRef.current = 10;
      }
  };

  const update = () => {
    if (gameState !== GameState.PLAYING) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;

    const enemies = entitiesRef.current.filter(e => e.type === 'enemy');
    const players = entitiesRef.current.filter(e => e.type === 'player' && !e.isDead);

    // 失败判定
    if (players.length === 0 && entitiesRef.current.some(e => e.type === 'player')) {
           setGameState(GameState.GAME_OVER);
           setStats({...statsRef.current});
           return;
    }

    // 波次管理逻辑
    if (waveStateRef.current.waveInProgress) {
        // 生成敌人
        const spawnRate = Math.max(30, 100 - statsRef.current.wave * 5);
        if (waveStateRef.current.enemiesSpawned < waveStateRef.current.maxEnemies && frameRef.current % spawnRate === 0) {
            const side = Math.random() > 0.5 ? -60 : canvas.width + 60;
            const hp = 50 + (statsRef.current.wave * 15);
            entitiesRef.current.push({
                id: `enemy_${frameRef.current}`,
                type: 'enemy',
                pos: { x: side, y: GROUND_Y },
                vel: { x: 0, y: 0 },
                width: 30, height: 60, color: '#ef4444',
                isGrounded: false, health: hp, maxHealth: hp, isDead: false,
                facingRight: side < canvas.width / 2,
                attackCooldown: 0, isAttacking: false, attackFrame: 0,
                skillCooldowns: { FIREBALL: 0, HEAL: 0, RAGE: 0 }, rageDuration: 0
            });
            waveStateRef.current.enemiesSpawned++;
        }

        // 波次完成判定
        if (waveStateRef.current.enemiesSpawned >= waveStateRef.current.maxEnemies && enemies.length === 0) {
            waveStateRef.current.waveInProgress = false;
            onWaveComplete(); // 增加技能点
            setGameState(GameState.SKILL_MENU);

            // 开启下一波 (逻辑在 SKILL_MENU 关闭时通过 startWave 触发，或者在这里预备)
            // 我们通过 App 传递 startWave 比较麻烦，直接在这里监听 gameState 变化比较好
            // 但这里直接修改 wave 状态即可，下次 update 循环会等待

            // 实际上，当用户在菜单点“下一波”，会把 GameState 设回 PLAYING
            // 我们需要检测到这一点并重置 waveState
        }
    } else {
        // 如果不在波次中（刚从菜单回来），开启新波次
        if (gameState === GameState.PLAYING && enemies.length === 0) {
            startWave(statsRef.current.wave + 1);
        }
    }

    statsRef.current.timeSurvived += 1/60;

    // --- 实体更新 ---
    entitiesRef.current.forEach(entity => {
      if (entity.isDead) return;

      // 狂暴状态衰减
      const isRaged = entity.rageDuration > 0;
      if (entity.rageDuration > 0) entity.rageDuration--;

      // 技能冷却衰减
      (Object.keys(entity.skillCooldowns) as SkillType[]).forEach(k => {
          if (entity.skillCooldowns[k] > 0) entity.skillCooldowns[k]--;
      });

      // 物理属性
      if (entity.type !== 'projectile') {
        entity.vel.y += GRAVITY;
        entity.vel.x *= FRICTION;
      }

      // 狂暴加速
      const speedMult = isRaged ? 1.5 : 1;

      entity.pos.x += entity.vel.x * speedMult;
      entity.pos.y += entity.vel.y;

      // 地面碰撞
      if (entity.type !== 'projectile') {
        if (entity.pos.y >= GROUND_Y) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
        } else {
            entity.isGrounded = false;
        }
        // 边界
        if (entity.pos.x < 15) entity.pos.x = 15;
        if (entity.pos.x > canvas.width - 15) entity.pos.x = canvas.width - 15;
      }

      // 攻击冷却
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 12) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      // --- Projectile Logic ---
      if (entity.type === 'projectile') {
          // 投射物飞行
          if (entity.pos.x < -100 || entity.pos.x > canvas.width + 100) {
              entity.isDead = true; // 超出屏幕消失
          }

          // 投射物碰撞检测 (Player projectiles hit enemies)
          entitiesRef.current.forEach(target => {
              if (target.type === 'enemy' && !target.isDead) {
                  const dx = target.pos.x - entity.pos.x;
                  const dy = (target.pos.y - 30) - (entity.pos.y);
                  if (Math.sqrt(dx*dx + dy*dy) < 40) {
                      // Hit!
                      target.health -= entity.maxHealth; // maxHealth stores damage
                      target.vel.x = entity.vel.x > 0 ? 10 : -10;
                      entity.isDead = true; // Projectile destroyed
                      spawnParticles(target.pos.x, target.pos.y - 30, '#f59e0b', 15);

                      if (target.health <= 0) {
                          target.isDead = true;
                          statsRef.current.score += 100 * statsRef.current.wave;
                          statsRef.current.enemiesKilled++;
                          spawnParticles(target.pos.x, target.pos.y - 30, target.color, 25);
                      }
                  }
              }
          });
          return; // Projectiles don't do player input logic
      }

      // --- Player Logic ---
      if (entity.type === 'player') {
        const isP1 = entity.playerIndex === 0;
        const up = isP1 ? 'KeyW' : 'ArrowUp';
        const left = isP1 ? 'KeyA' : 'ArrowLeft';
        const right = isP1 ? 'KeyD' : 'ArrowRight';
        const attack = isP1 ? 'Space' : 'Enter';

        // Skills
        const skill1 = isP1 ? 'KeyQ' : 'ShiftRight';
        const skill2 = isP1 ? 'KeyE' : 'ControlRight';

        if (keysRef.current.has(left)) {
          entity.vel.x -= MOVE_SPEED;
          entity.facingRight = false;
        }
        if (keysRef.current.has(right)) {
          entity.vel.x += MOVE_SPEED;
          entity.facingRight = true;
        }
        if (keysRef.current.has(up) && entity.isGrounded) {
          entity.vel.y = JUMP_FORCE;
        }

        // Skill Input
        if (keysRef.current.has(skill1)) useSkill(entity, 'FIREBALL');
        // Skill 2 (Heal or Rage based on slot)
        // 简单起见，我们假设 E/Ctrl 触发 技能槽2，玩家如果有 HEAL 就用 HEAL，有 RAGE 就用 RAGE
        // 优先判断 RAGE (Cost 3), 然后 HEAL (Cost 2)。或者根据 unlocked。
        // 这里做一个简单的映射： Skill 2 键位尝试触发 HEAL 或 RAGE
        if (keysRef.current.has(skill2)) {
             if (playerSkills[entity.playerIndex!].levels['RAGE'] > 0) useSkill(entity, 'RAGE');
             else useSkill(entity, 'HEAL');
        }

        // Attack Logic
        if (keysRef.current.has(attack) && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = isRaged ? 15 : ATTACK_COOLDOWN; // Rage reduces cooldown

          const hitX = entity.facingRight ? entity.pos.x + 50 : entity.pos.x - 50;
          const dmg = isRaged ? ATTACK_DAMAGE * 2 : ATTACK_DAMAGE;

          entitiesRef.current.forEach(target => {
            if (target.type === 'enemy' && !target.isDead) {
                const dx = target.pos.x - hitX;
                const dy = (target.pos.y - 30) - (entity.pos.y - 30);
                if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                    target.health -= dmg;
                    target.vel.x = entity.facingRight ? 15 : -15;
                    target.vel.y = -8;
                    shakeRef.current = isRaged ? 8 : 5;
                    spawnParticles(target.pos.x, target.pos.y - 30, '#fff', 5);

                    if (target.health <= 0) {
                        target.isDead = true;
                        statsRef.current.score += 100 * statsRef.current.wave;
                        statsRef.current.enemiesKilled++;
                        spawnParticles(target.pos.x, target.pos.y - 30, target.color, 25);
                    }
                }
            }
          });
        }
      }

      // --- Enemy Logic ---
      if (entity.type === 'enemy') {
        let targetPlayer: Entity | null = null;
        let minDist = Infinity;

        entitiesRef.current.forEach(p => {
            if (p.type === 'player' && !p.isDead) {
                const dist = Math.abs(p.pos.x - entity.pos.x);
                if (dist < minDist) {
                    minDist = dist;
                    targetPlayer = p;
                }
            }
        });

        if (targetPlayer) {
            if (targetPlayer.pos.x > entity.pos.x + 40) {
                entity.vel.x += MOVE_SPEED * 0.5;
                entity.facingRight = true;
            } else if (targetPlayer.pos.x < entity.pos.x - 40) {
                entity.vel.x -= MOVE_SPEED * 0.5;
                entity.facingRight = false;
            }

            const dist = Math.abs(targetPlayer.pos.x - entity.pos.x);
            if (dist < 60 && entity.attackCooldown === 0) {
                 entity.isAttacking = true;
                 entity.attackCooldown = ATTACK_COOLDOWN + 30;
                 if (frameRef.current % 5 === 0) {
                    targetPlayer.health -= 8 + statsRef.current.wave; 
                    targetPlayer.vel.x = entity.facingRight ? 8 : -8;
                    targetPlayer.vel.y = -4;
                    spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y - 30, '#ff0000', 5);
                    shakeRef.current = 3;
                    if (targetPlayer.health <= 0) {
                        targetPlayer.isDead = true;
                        spawnParticles(targetPlayer.pos.x, targetPlayer.pos.y, targetPlayer.color, 40);
                    }
                 }
            }
        }
      }
    });

    entitiesRef.current = entitiesRef.current.filter(e => e.type === 'player' || !e.isDead);

    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += 0.5; 
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current.filter(e => e.type === 'player')]);
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);

    // Background
    ctx.fillStyle = '#222';
    ctx.fillRect(100, GROUND_Y - 200, 100, 200);
    ctx.fillRect(300, GROUND_Y - 300, 150, 300);
    ctx.fillRect(600, GROUND_Y - 150, 80, 150);
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    ctx.strokeStyle = '#555';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);
      if (!entity.facingRight) ctx.scale(-1, 1);

      // Projectile Draw
      if (entity.type === 'projectile') {
          ctx.fillStyle = entity.color;
          ctx.beginPath();
          ctx.arc(0, 0, 10, 0, Math.PI * 2);
          ctx.fill();
          // Trail
          ctx.fillStyle = 'rgba(255, 165, 0, 0.5)';
          ctx.beginPath();
          ctx.arc(-15, 0, 8, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
          return;
      }

      // Rage Effect
      if (entity.rageDuration > 0) {
          ctx.shadowColor = 'red';
          ctx.shadowBlur = 20;
          ctx.strokeStyle = '#fca5a5'; // lighter red
      } else {
          const color = entity.isDead ? '#555' : entity.color;
          ctx.strokeStyle = color;
          ctx.fillStyle = color;
      }

      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // Stickman Draw
      const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
      const runCycle = Math.sin(frameRef.current * 0.5) * 15;
      const runOffset = isRunning ? runCycle : 0;

      const hipY = -35;
      const headY = -75;

      // Legs
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(-10 + runOffset, 0); 
      ctx.moveTo(0, hipY);
      ctx.lineTo(10 - runOffset, 0); 
      ctx.stroke();

      // Body
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(0, headY + 10);
      ctx.stroke();

      // Head
      ctx.beginPath();
      ctx.arc(0, headY, 12, 0, Math.PI * 2);
      ctx.fillStyle = entity.rageDuration > 0 ? '#ff0000' : (entity.isDead ? '#555' : entity.color);
      ctx.fill();

      // Arms
      ctx.beginPath();
      ctx.strokeStyle = entity.rageDuration > 0 ? '#ff0000' : (entity.isDead ? '#555' : entity.color);
      const shoulderY = -65;

      if (entity.isAttacking) {
          const punchExtend = 15 + (entity.attackFrame * 3);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-10, shoulderY + 10);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(punchExtend, shoulderY);

          ctx.save();
          ctx.shadowBlur = 15;
          ctx.shadowColor = entity.color;
          ctx.fillStyle = '#fff';
          ctx.fillRect(punchExtend, shoulderY - 5, 20, 10); 
          ctx.restore();
      } else {
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-15 - runOffset, shoulderY + 15);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(15 + runOffset, shoulderY + 15);
      }
      ctx.stroke();

      if (entity.type === 'enemy' && !entity.isDead) {
          ctx.restore(); 
          ctx.save();
          ctx.translate(entity.pos.x, entity.pos.y - 100);
          ctx.fillStyle = 'red';
          ctx.fillRect(-20, 0, 40, 4);
          ctx.fillStyle = '#0f0';
          ctx.fillRect(-20, 0, 40 * (entity.health / entity.maxHealth), 4);
      }

      ctx.restore();
    });

    ctx.restore(); 
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]); // Restart loop if gamestate changes back to playing

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-neutral-900"
    />
  );
};

export default GameCanvas;

