import React, { useEffect, useState } from 'react';
import { GameState, GameStats } from '../types';
import { getTacticalAnalysis } from '../services/geminiService';

interface GameOverProps {
  stats: GameStats;
  onRestart: () => void;
  onMenu: () => void;
}

const GameOver: React.FC<GameOverProps> = ({ stats, onRestart, onMenu }) => {
  const [analysis, setAnalysis] = useState<string>("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    getTacticalAnalysis(stats).then(text => {
      if (mounted) {
        setAnalysis(text);
        setLoading(false);
      }
    });
    return () => { mounted = false; };
  }, [stats]);

  const p1Won = stats.winner === 'P1';
  const winnerColor = p1Won ? 'text-blue-500' : 'text-red-500';
  const titleText = stats.winner ? `${stats.winner} 获胜!` : '平 局';

  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md animate-fade-in">
      <div className="w-full max-w-4xl bg-[#111] border border-gray-800 shadow-2xl relative overflow-hidden flex flex-col md:flex-row rounded-xl">

        {/* 左侧：胜负展示 */}
        <div className="flex-1 p-10 flex flex-col justify-center items-center border-r border-gray-800 bg-gradient-to-br from-gray-900 to-black">
            <h2 className={`text-7xl font-comic italic font-black ${winnerColor} mb-4 drop-shadow-lg transform -rotate-3`}>
                {titleText}
            </h2>
            <div className="text-6xl mb-8">
                {p1Won ? '👑' : ''} {p1Won ? '🟦' : '🟥'} {p1Won ? '' : '👑'}
            </div>

            <div className="flex flex-col gap-4 w-full">
                <button onClick={onRestart} className="w-full bg-white text-black font-bold py-4 hover:scale-105 transition-transform uppercase tracking-wider skew-x-[-10deg]">
                    再来一局
                </button>
                <button onClick={onMenu} className="w-full bg-transparent border border-gray-600 text-gray-400 font-bold py-4 hover:border-white hover:text-white transition-colors uppercase tracking-wider skew-x-[-10deg]">
                    返回主菜单
                </button>
            </div>
        </div>

        {/* 右侧：AI 赛评 */}
        <div className="flex-1 p-8 bg-black relative">
            <div className="absolute top-4 right-4 text-xs text-gray-600 font-mono">GEMINI SPORTS ANALYTICS</div>
            <h3 className="text-purple-500 font-bold mb-6 text-xl flex items-center gap-2">
              <span className="w-2 h-2 bg-purple-500 rounded-full animate-pulse"></span>
              赛后复盘
            </h3>

            <div className="font-mono text-sm text-gray-300 leading-relaxed min-h-[200px]">
              {loading ? (
                <div className="space-y-2 opacity-50">
                    <div className="h-2 bg-gray-800 rounded w-3/4 animate-pulse"></div>
                    <div className="h-2 bg-gray-800 rounded w-full animate-pulse"></div>
                    <div className="h-2 bg-gray-800 rounded w-5/6 animate-pulse"></div>
                </div>
              ) : (
                <div className="typing-cursor">
                  {analysis}
                </div>
              )}
            </div>

            <div className="mt-8 pt-4 border-t border-gray-900 flex justify-between text-xs text-gray-500">
                <span>MODE: {stats.mode}</span>
                <span>DURATION: {Math.floor(stats.duration)}s</span>
            </div>
        </div>
      </div>
    </div>
  );
};

