import React from 'react';
import { Entity, GameStats } from '../types';

interface GameUIProps {
  stats: GameStats;
  players: Entity[];
}

const FighterHUD: React.FC<{ player: Entity; align: 'left' | 'right' }> = ({ player, align }) => {
  if (!player) return null;

  const hpPct = Math.max(0, (player.health / player.maxHealth) * 100);
  const isDanger = hpPct < 30;

  return (
    <div className={`flex flex-col w-96 ${align === 'right' ? 'items-end' : 'items-start'}`}>
      <div className={`flex items-end gap-2 mb-1 ${align === 'right' ? 'flex-row-reverse' : 'flex-row'}`}>
        <span className="text-4xl font-comic italic font-black text-white drop-shadow-md">
            {player.id === 'p1' ? 'P1' : (player.type === 'player' ? (player.id === 'p2' ? 'P2' : 'CPU') : 'CPU')}
        </span>
        <div 
          className="w-4 h-4 mb-2 rotate-45"
          style={{ backgroundColor: player.color, boxShadow: `0 0 10px ${player.color}` }}
        ></div>
      </div>

      {/* 血条外框 */}
      <div className={`w-full h-8 bg-gray-800 border-2 border-gray-600 transform ${align === 'left' ? '-skew-x-12' : 'skew-x-12'} p-1 overflow-hidden relative shadow-xl`}>
         {/* 血量 */}
         <div className={`h-full transition-all duration-200 ${isDanger ? 'animate-pulse' : ''}`}
              style={{ 
                  width: `${hpPct}%`, 
                  float: align === 'left' ? 'left' : 'right',
                  backgroundColor: player.color,
                  boxShadow: `0 0 15px ${player.color}`
              }}>
         </div>
         {/* 高光 */}
         <div className="absolute top-0 left-0 w-full h-1/2 bg-white/10 pointer-events-none"></div>
      </div>
    </div>
  );
};

const GameUI: React.FC<GameUIProps> = ({ stats, players }) => {
  return (
    <div className="absolute inset-0 pointer-events-none p-8 flex flex-col justify-between">
      {/* 顶部格斗 HUD */}
      <div className="flex justify-between items-start">
        <FighterHUD player={players[0]} align="left" />

        {/* VS 标志 */}
        <div className="flex flex-col items-center pt-2">
            <span className="text-6xl font-black italic text-red-600 font-comic drop-shadow-[0_0_15px_rgba(220,38,38,0.8)] animate-pulse">
