import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode } from '../types';
import { playJumpSound, playAttackSound, playHitSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数调整：慢节奏 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧，蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // P2/CPU (右侧，黄)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15', // 黄色 Yellow-400
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2
          });
      }
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // --- 实体循环 ---
    entitiesRef.current.forEach(entity => {
      // === 物理引擎 ===
      entity.vel.y += GRAVITY;

      // 胜利者/正常人 受到摩擦力
      if (!entity.isLoser) {
          // 下蹲时摩擦力极大 (停止移动)
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // === 地面碰撞 ===
      if (!entity.isLoser) {
        if (entity.pos.y >= GROUND_Y) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
        } else {
            entity.isGrounded = false;
        }

        // 边界限制
        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      // === 胜利/失败处理 ===
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;
          }
          return;
      }

      // === 攻击冷却 ===
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      // === 输入与AI ===
      let moveLeft = false;
      let moveRight = false;
      let jump = false;
      let crouch = false;
      let attack = false;

      // P1 Input
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // P2 Input or AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // === AI ===
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                const dist = p1.pos.x - entity.pos.x;
                const absDist = Math.abs(dist);

                // 躲避判定：如果对方在攻击且距离很近，尝试下蹲
                const danger = p1.isAttacking && absDist < ATTACK_RANGE + 20;

                if (danger && Math.random() < 0.6) {
                    crouch = true; // 60% 概率下蹲躲避
                } else {
                    // 移动
                    if (absDist > ATTACK_RANGE - 10) {
                        if (dist > 0) moveRight = true;
                        else moveLeft = true;
                    } else if (absDist < 40) {
                        if (dist > 0) moveLeft = true;
                        else moveRight = true;
                    }

                    // 攻击
                    if (absDist < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                        if (Math.random() < 0.05) attack = true;
                    }

                    // 跳跃
                    if (entity.isGrounded && Math.random() < 0.01) jump = true;
                }
                entity.facingRight = dist > 0;
            }
          }
      }

      // 状态应用
      entity.isCrouching = crouch && entity.isGrounded;

      // 移动 (下蹲时不可移动)
      if (!entity.isCrouching) {
          if (moveLeft) {
              entity.vel.x -= MOVE_SPEED;
              entity.facingRight = false;
          }
          if (moveRight) {
              entity.vel.x += MOVE_SPEED;
              entity.facingRight = true;
          }
      }

      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // 攻击与判定
      // 下蹲时也可以攻击（下段攻击），但这里简化为必须站立攻击或者下蹲攻击
      if (attack && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;
          // 如果下蹲攻击，则强制站立（简单的实现）或者允许下蹲拳
          // 暂时设定：攻击会解除下蹲状态，或者必须站立才能攻击
          if (entity.isCrouching) {
             // 允许下蹲攻击，但视觉上可能是个低拳
          }

          playAttackSound(); 

          // 攻击判定框 (Hitbox)
          // 站立攻击判定点较高 (y - 50)，下蹲者 (头部 y - 40) 可以躲过
          const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
          // 如果攻击者下蹲，攻击点变低
          const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

          entitiesRef.current.forEach(target => {
              if (target !== entity && !target.isDead) {
                  const dx = target.pos.x - hitX;

                  // 目标的受击中心
                  // 如果目标下蹲，受击中心降低，且高度变低
                  const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                  const dy = targetCenterY - hitY;

                  // 判定距离
                  if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                      // **核心躲避逻辑**
                      // 如果是站立攻击(HitY 高) 打 下蹲者(CenterY 低)，且距离判定虽然过了但实际上应该Miss
                      // 简单处理：如果攻击者站立，而目标下蹲，则免疫伤害（模拟闪避上段攻击）
                      if (!entity.isCrouching && target.isCrouching) {
                          // DODGE!
                          spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2); // 灰色闪避粒子
                          return; 
                      }

                      // 命中处理
                      target.health -= ATTACK_DAMAGE;
                      target.vel.x = entity.facingRight ? 10 : -10;
                      target.vel.y = -5;

                      shakeRef.current = 8;
                      spawnParticles(hitX, hitY, target.color, 8);
                      playHitSound();

                      if (target.health <= 0) {
                          target.health = 0;
                          target.isDead = true;
                          target.isLoser = true;
                          entity.isWinner = true;
                          statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                          setGameState(GameState.VICTORY_ANIMATION);
                          setTimeout(() => {
                              setGameState(GameState.GAME_OVER);
                          }, 3000);
                      }
                  }
              }
          });
      }
    });

    // --- 粒子更新 ---
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += 0.5;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    // 同步
    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清屏
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 震屏
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }
    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // 背景柱子
    ctx.fillStyle = '#222';
    ctx.fillRect(100, GROUND_Y - 300, 60, 300);
    ctx.fillRect(canvas.width - 160, GROUND_Y - 300, 60, 300);

    // 粒子
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    // 实体
    entitiesRef.current.forEach(entity => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }

      if (!entity.facingRight) ctx.scale(-1, 1);

      const color = entity.isLoser ? '#555' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // --- 绘制火柴人 ---
      // 姿态参数
      let hipY = -40;
      let headY = -85;

      // 下蹲调整
      if (entity.isCrouching) {
          hipY = -25;
          headY = -55;
      }

      const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded && !entity.isLoser;
      const runCycle = Math.sin(frameRef.current * 0.4) * 15;
      const runOffset = isRunning ? runCycle : 0;

      // 腿
      if (entity.isLoser) {
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, 10);
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, 15);
          ctx.stroke();
      } else if (entity.isCrouching) {
          // 下蹲腿型 (像 M 形)
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-15, -5); 
          ctx.lineTo(-10, 0);
          ctx.moveTo(0, hipY);
          ctx.lineTo(15, -5);
          ctx.lineTo(10, 0);
          ctx.stroke();
      } else {
          // 站立/跑动
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-12 + runOffset, 0); 
          ctx.moveTo(0, hipY);
          ctx.lineTo(12 - runOffset, 0); 
          ctx.stroke();
      }

      // 躯干
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(0, headY + 12);
      ctx.stroke();

      // 头
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      ctx.arc(renderHeadX, renderHeadY, 14, 0, Math.PI * 2);
      ctx.fill();

      // 皇冠
      if (entity.isWinner) {
          ctx.save();
          ctx.fillStyle = '#FFD700';
          ctx.strokeStyle = '#DAA520';
          ctx.lineWidth = 2;
          ctx.translate(0, headY - 25);
          ctx.beginPath();
          ctx.moveTo(-15, 0);
          ctx.lineTo(-15, -15);
          ctx.lineTo(-8, -5);
          ctx.lineTo(0, -20);
          ctx.lineTo(8, -5);
          ctx.lineTo(15, -15);
          ctx.lineTo(15, 0);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();
          ctx.restore();
      }

      // 手臂
      ctx.beginPath();
      const shoulderY = entity.isCrouching ? headY + 15 : -70;

      if (entity.isLoser) {
           ctx.moveTo(0, shoulderY);
           ctx.lineTo(-10, shoulderY + 30);
           ctx.moveTo(0, shoulderY);
           ctx.lineTo(10, shoulderY + 30);
      } else if (entity.isAttacking) {
          const punchExtend = 20 + (entity.attackFrame * 4);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-15, shoulderY + 15);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(punchExtend, shoulderY);

          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 10;
          ctx.fillRect(punchExtend, shoulderY - 8, 25, 16);
          ctx.restore();
      } else if (entity.isWinner) {
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-20, shoulderY - 30);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(20, shoulderY - 30);
      } else if (entity.isCrouching) {
          // 下蹲防御姿态：手放在脸前
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(15, shoulderY - 5);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(10, shoulderY + 5);
      } else {
          // 战斗姿态
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(20, shoulderY - 10);
          ctx.lineTo(30, shoulderY - 25);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(10, shoulderY + 10);
      }
      ctx.stroke();

      ctx.restore();
    });

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-neutral-900"
    />
  );
};

export default GameCanvas;

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  VICTORY_ANIMATION // 新增：胜利动画阶段
}

export type GameMode = 'PVE' | 'PVP';

export interface Vector {
  x: number;
  y: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  isCrouching: boolean; // 新增：是否下蹲
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number;
  type: 'player'; // 都是玩家，只是阵营不同
  playerIndex: number; // 0 (P1) 或 1 (P2/CPU)
  isWinner?: boolean; // 胜利标记
  isLoser?: boolean;  // 失败标记
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  gravity?: number; // 新增：自定义重力，用于撒花效果
}

export interface GameStats {
  winner: string | null; // 'P1' 或 'P2'
  mode: GameMode;
  duration: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode } from '../types';
import { playJumpSound, playAttackSound, playHitSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数调整：慢节奏 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧，蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // P2/CPU (右侧，黄)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15', // 黄色 Yellow-400
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2,
              gravity: 0.5 // 默认重力
          });
      }
  };

  const spawnConfetti = (width: number) => {
      // 生成多彩纸带/花瓣
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; // 从屏幕顶部上方生成
      const color = colors[Math.floor(Math.random() * colors.length)];

      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { 
            x: (Math.random() - 0.5) * 2, // 左右飘动
            y: Math.random() * 2 + 1      // 慢慢下落
          },
          life: 200, // 存活时间长
          maxLife: 200,
          color: color,
          size: Math.random() * 4 + 3,
          gravity: 0.02 // 极低重力，像纸片一样飘
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // --- 实体循环 ---
    entitiesRef.current.forEach(entity => {
      // === 物理引擎 ===
      // 只有非胜利者才一直受标准重力影响，胜利者会在后面被飞行逻辑接管
      if (!entity.isWinner) {
        entity.vel.y += GRAVITY;
      }

      if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // === 地面碰撞 ===
      if (!entity.isLoser && !entity.isWinner) { // 胜利者也不受地面束缚了，因为要飞
        if (entity.pos.y >= GROUND_Y) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
        } else {
            entity.isGrounded = false;
        }

        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      } else if (entity.isWinner) {
          // 胜利者边界判定 (防止飞出屏幕左右)
          if (entity.pos.x < 20) entity.pos.x = 20;
          if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      // === 胜利/失败处理 ===
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;

              // === 飞行逻辑 ===
              // 目标：屏幕中央上方 (1/3 高度)
              const targetX = canvas.width / 2;
              const targetY = canvas.height / 3;

              // 简单的平滑插值移动 (Lerp-like force)
              entity.vel.x = (targetX - entity.pos.x) * 0.05;
              entity.vel.y = (targetY - entity.pos.y) * 0.05;

              // 悬停时的轻微浮动效果
              entity.vel.y += Math.sin(frameRef.current * 0.05) * 0.5;

              // === 撒花 ===
              if (frameRef.current % 3 === 0) { // 高频撒花
                  spawnConfetti(canvas.width);
              }

              // 胜利者直接跳过输入检测
              return; 
          }
          // 失败者继续受重力影响掉落
      }

      // === 攻击冷却 ===
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      // === 输入与AI ===
      let moveLeft = false;
      let moveRight = false;
      let jump = false;
      let crouch = false;
      let attack = false;

      // P1 Input
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // P2 Input or AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // === AI ===
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                const dist = p1.pos.x - entity.pos.x;
                const absDist = Math.abs(dist);

                const danger = p1.isAttacking && absDist < ATTACK_RANGE + 20;

                if (danger && Math.random() < 0.6) {
                    crouch = true;
                } else {
                    if (absDist > ATTACK_RANGE - 10) {
                        if (dist > 0) moveRight = true;
                        else moveLeft = true;
                    } else if (absDist < 40) {
                        if (dist > 0) moveLeft = true;
                        else moveRight = true;
                    }

                    if (absDist < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                        if (Math.random() < 0.05) attack = true;
                    }

                    if (entity.isGrounded && Math.random() < 0.01) jump = true;
                }
                entity.facingRight = dist > 0;
            }
          }
      }

      // 状态应用
      entity.isCrouching = crouch && entity.isGrounded;

      if (!entity.isCrouching) {
          if (moveLeft) {
              entity.vel.x -= MOVE_SPEED;
              entity.facingRight = false;
          }
          if (moveRight) {
              entity.vel.x += MOVE_SPEED;
              entity.facingRight = true;
          }
      }

      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      if (attack && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;

          playAttackSound(); 

          const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
          const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

          entitiesRef.current.forEach(target => {
              if (target !== entity && !target.isDead) {
                  const dx = target.pos.x - hitX;

                  const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                  const dy = targetCenterY - hitY;

                  if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                      if (!entity.isCrouching && target.isCrouching) {
                          spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                          return; 
                      }

                      target.health -= ATTACK_DAMAGE;
                      target.vel.x = entity.facingRight ? 10 : -10;
                      target.vel.y = -5;

                      shakeRef.current = 8;
                      spawnParticles(hitX, hitY, target.color, 8);
                      playHitSound();

                      if (target.health <= 0) {
                          target.health = 0;
                          target.isDead = true;
                          target.isLoser = true;
                          entity.isWinner = true;
                          statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                          setGameState(GameState.VICTORY_ANIMATION);
                          // 延长胜利展示时间到 5 秒
                          setTimeout(() => {
                              setGameState(GameState.GAME_OVER);
                          }, 5000);
                      }
                  }
              }
          });
      }
    });

    // --- 粒子更新 ---
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        // 使用粒子自定义重力，默认为 0.5
        const g = p.gravity !== undefined ? p.gravity : 0.5;
        p.vel.y += g;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    // 同步
    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清屏
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 震屏
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }
    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // 背景柱子
    ctx.fillStyle = '#222';
    ctx.fillRect(100, GROUND_Y - 300, 60, 300);
    ctx.fillRect(canvas.width - 160, GROUND_Y - 300, 60, 300);

    // 粒子 (包括撒花)
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;

        ctx.beginPath();
        if (p.gravity && p.gravity < 0.1) {
            // 纸带/花瓣是矩形，并且会旋转（简单模拟）
            ctx.save();
            ctx.translate(p.pos.x, p.pos.y);
            ctx.rotate(frameRef.current * 0.1 + parseFloat(p.id)); // 随机旋转
            ctx.fillRect(-p.size, -p.size/2, p.size*2, p.size);
            ctx.restore();
        } else {
            // 普通圆形粒子
            ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 1.0;
    });

    // 实体
    entitiesRef.current.forEach(entity => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }

      if (!entity.facingRight) ctx.scale(-1, 1);

      const color = entity.isLoser ? '#555' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // --- 绘制火柴人 ---
      // 姿态参数
      let hipY = -40;
      let headY = -85;

      // 下蹲调整
      if (entity.isCrouching) {
          hipY = -25;
          headY = -55;
      }

      // 飞行姿态 (双腿伸直微弯)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
         hipY = -40; // 恢复站立高度
         // 腿
         ctx.beginPath();
         ctx.moveTo(0, hipY);
         ctx.lineTo(-5, 5); 
         ctx.moveTo(0, hipY);
         ctx.lineTo(5, 10); 
         ctx.stroke();
      } else {
          // 常规腿部逻辑
          const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded && !entity.isLoser;
          const runCycle = Math.sin(frameRef.current * 0.4) * 15;
          const runOffset = isRunning ? runCycle : 0;

          if (entity.isLoser) {
              ctx.beginPath();
              ctx.moveTo(0, hipY);
              ctx.lineTo(-5, 10);
              ctx.moveTo(0, hipY);
              ctx.lineTo(5, 15);
              ctx.stroke();
          } else if (entity.isCrouching) {
              ctx.beginPath();
              ctx.moveTo(0, hipY);
              ctx.lineTo(-15, -5); 
              ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY);
              ctx.lineTo(15, -5);
              ctx.lineTo(10, 0);
              ctx.stroke();
          } else {
              ctx.beginPath();
              ctx.moveTo(0, hipY);
              ctx.lineTo(-12 + runOffset, 0); 
              ctx.moveTo(0, hipY);
              ctx.lineTo(12 - runOffset, 0); 
              ctx.stroke();
          }
      }

      // 躯干
      ctx.beginPath();
      ctx.moveTo(0, hipY);
      ctx.lineTo(0, headY + 12);
      ctx.stroke();

      // 头
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      ctx.arc(renderHeadX, renderHeadY, 14, 0, Math.PI * 2);
      ctx.fill();

      // 皇冠
      if (entity.isWinner) {
          ctx.save();
          ctx.fillStyle = '#FFD700';
          ctx.strokeStyle = '#DAA520';
          ctx.lineWidth = 2;
          ctx.translate(0, headY - 25);
          ctx.beginPath();
          ctx.moveTo(-15, 0);
          ctx.lineTo(-15, -15);
          ctx.lineTo(-8, -5);
          ctx.lineTo(0, -20);
          ctx.lineTo(8, -5);
          ctx.lineTo(15, -15);
          ctx.lineTo(15, 0);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          // 皇冠闪光
          if (frameRef.current % 30 < 10) {
              ctx.fillStyle = 'white';
              ctx.fillRect(-10, -10, 2, 2);
              ctx.fillRect(10, -8, 2, 2);
          }
          ctx.restore();
      }

      // 手臂
      ctx.beginPath();
      const shoulderY = entity.isCrouching ? headY + 15 : -70;

      if (entity.isLoser) {
           ctx.moveTo(0, shoulderY);
           ctx.lineTo(-10, shoulderY + 30);
           ctx.moveTo(0, shoulderY);
           ctx.lineTo(10, shoulderY + 30);
      } else if (entity.isAttacking) {
          const punchExtend = 20 + (entity.attackFrame * 4);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-15, shoulderY + 15);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(punchExtend, shoulderY);

          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 10;
          ctx.fillRect(punchExtend, shoulderY - 8, 25, 16);
          ctx.restore();
      } else if (entity.isWinner) {
          // 胜利飞行姿态：双手张开
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(-20, shoulderY - 20);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(20, shoulderY - 20);
      } else if (entity.isCrouching) {
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(15, shoulderY - 5);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(10, shoulderY + 5);
      } else {
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(20, shoulderY - 10);
          ctx.lineTo(30, shoulderY - 25);
          ctx.moveTo(0, shoulderY);
          ctx.lineTo(10, shoulderY + 10);
      }
      ctx.stroke();

      ctx.restore();
    });

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-neutral-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode } from '../types';
import { playJumpSound, playAttackSound, playHitSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧，蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // P2/CPU (右侧，黄)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15', // 黄色 Yellow-400
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2,
              gravity: 0.5 
          });
      }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];

      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { 
            x: (Math.random() - 0.5) * 2, 
            y: Math.random() * 2 + 1
          },
          life: 200,
          maxLife: 200,
          color: color,
          size: Math.random() * 4 + 3,
          gravity: 0.02 
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // --- 实体更新 ---
    entitiesRef.current.forEach(entity => {
      if (!entity.isWinner) {
        entity.vel.y += GRAVITY;
      }

      if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      if (!entity.isLoser && !entity.isWinner) { 
        if (entity.pos.y >= GROUND_Y) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
        } else {
            entity.isGrounded = false;
        }

        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      } else if (entity.isWinner) {
          if (entity.pos.x < 20) entity.pos.x = 20;
          if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      // === 胜利飞行逻辑 ===
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;

              // 目标：屏幕中央上方
              const targetX = canvas.width / 2;
              const targetY = canvas.height / 3;

              // 平滑飞行
              entity.vel.x = (targetX - entity.pos.x) * 0.04;
              entity.vel.y = (targetY - entity.pos.y) * 0.04;

              // 悬停浮动
              entity.vel.y += Math.sin(frameRef.current * 0.05) * 0.5;

              if (frameRef.current % 3 === 0) { 
                  spawnConfetti(canvas.width);
              }
              return; 
          }
      }

      // === 战斗逻辑 ===
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                const dist = p1.pos.x - entity.pos.x;
                const absDist = Math.abs(dist);
                const danger = p1.isAttacking && absDist < ATTACK_RANGE + 20;

                if (danger && Math.random() < 0.6) {
                    crouch = true;
                } else {
                    if (absDist > ATTACK_RANGE - 10) {
                        dist > 0 ? moveRight = true : moveLeft = true;
                    } else if (absDist < 40) {
                        dist > 0 ? moveLeft = true : moveRight = true;
                    }
                    if (absDist < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                        if (Math.random() < 0.05) attack = true;
                    }
                    if (entity.isGrounded && Math.random() < 0.01) jump = true;
                }
                entity.facingRight = dist > 0;
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;

      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }

      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      if (attack && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;
          playAttackSound(); 

          const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
          const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

          entitiesRef.current.forEach(target => {
              if (target !== entity && !target.isDead) {
                  const dx = target.pos.x - hitX;
                  const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                  const dy = targetCenterY - hitY;

                  if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                      if (!entity.isCrouching && target.isCrouching) {
                          spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                          return; 
                      }

                      target.health -= ATTACK_DAMAGE;
                      target.vel.x = entity.facingRight ? 10 : -10;
                      target.vel.y = -5;

                      shakeRef.current = 8;
                      spawnParticles(hitX, hitY, target.color, 8);
                      playHitSound();

                      if (target.health <= 0) {
                          target.health = 0;
                          target.isDead = true;
                          target.isLoser = true;
                          entity.isWinner = true;
                          statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                          setGameState(GameState.VICTORY_ANIMATION);
                          setTimeout(() => {
                              setGameState(GameState.GAME_OVER);
                          }, 5000);
                      }
                  }
              }
          });
      }
    });

    // --- 粒子更新 ---
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        const g = p.gravity !== undefined ? p.gravity : 0.5;
        p.vel.y += g;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  // === 绘制动态背景 ===
  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      // 1. 深色基础
      ctx.fillStyle = '#0f172a'; // Slate-900
      ctx.fillRect(0, 0, width, height);

      // 2. 动态网格地板
      const time = frameRef.current;
      const gridSpeed = 2;
      const offset = (time * gridSpeed) % 100;

      ctx.strokeStyle = '#334155'; // Slate-700
      ctx.lineWidth = 1;

      // 垂直线 (移动)
      ctx.beginPath();
      for (let x = -offset; x < width; x += 100) {
          ctx.moveTo(x, GROUND_Y);
          ctx.lineTo(x, height);
      }
      ctx.stroke();

      // 水平线 (透视效果模拟 - 实际上这里用平行线简单处理)
      ctx.beginPath();
      for (let y = GROUND_Y; y < height; y += 50) {
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
      }
      ctx.stroke();

      // 3. 背景装饰柱动态发光
      const pulse = Math.sin(time * 0.05) * 0.5 + 0.5; // 0~1
      const pillarColor = `rgba(50, 60, 80, ${0.5 + pulse * 0.2})`;

      ctx.fillStyle = pillarColor;
      ctx.fillRect(100, GROUND_Y - 300, 80, 300);
      ctx.fillRect(width - 180, GROUND_Y - 300, 80, 300);

      // 柱子高光线条
      ctx.strokeStyle = `rgba(100, 200, 255, ${0.1 + pulse * 0.2})`;
      ctx.lineWidth = 2;
      ctx.strokeRect(100, GROUND_Y - 300, 80, 300);
      ctx.strokeRect(width - 180, GROUND_Y - 300, 80, 300);

      // 4. 地面分界线
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#000';
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(0, GROUND_Y);
      ctx.lineTo(width, GROUND_Y);
      ctx.stroke();
      ctx.shadowBlur = 0;
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      // 失败者：旋转掉落
      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }

      // 超人飞行模式：旋转身体
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // 向中心飞，根据速度或固定角度倾斜
          // 这里使用固定的 -45 度（向上飞）或者根据 X 轴方向调整
          const tilt = -Math.PI / 4; 
          ctx.rotate(tilt);
      } else if (!entity.facingRight) {
          ctx.scale(-1, 1);
      }

      const color = entity.isLoser ? '#64748b' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;

      // === 健全肢体渲染 ===
      // 加粗线条，使用圆角
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // 坐标定义
      let headY = -85;
      let neckY = -70; // 脖子/肩膀中心
      let hipY = -40; // 臀部中心

      if (entity.isCrouching) {
          headY = -55;
          neckY = -40;
          hipY = -25;
      }

      // 1. 身体 (Torso)
      ctx.beginPath();
      ctx.moveTo(0, neckY);
      ctx.lineTo(0, hipY);
      ctx.stroke();

      // 2. 头部 (Head)
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      // 头部稍微大一点
      ctx.arc(renderHeadX, renderHeadY, 15, 0, Math.PI * 2);
      ctx.fill();

      // 3. 腿部 (Legs)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 超人飞行姿态腿部 ===
          // 双腿并拢伸直向后
          ctx.beginPath();
          // 腿1
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, hipY + 40);
          // 腿2
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, hipY + 40); // 稍微错开
          ctx.stroke();
      } else if (entity.isLoser) {
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, 10);
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, 15);
          ctx.stroke();
      } else if (entity.isCrouching) {
          // 下蹲 M 型腿
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-18, -5); 
          ctx.lineTo(-10, 0);
          ctx.moveTo(0, hipY);
          ctx.lineTo(18, -5);
          ctx.lineTo(10, 0);
          ctx.stroke();
      } else {
          // 跑步动画
          const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
          const runCycle = Math.sin(frameRef.current * 0.4);

          ctx.beginPath();
          if (isRunning) {
              // 跑步时膝盖弯曲
              // 后腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(-15 * Math.cos(runCycle), 0);
              // 前腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(15 * Math.cos(runCycle), 0);
          } else {
              // 站立 (微张)
              ctx.moveTo(0, hipY);
              ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY);
              ctx.lineTo(10, 0);
          }
          ctx.stroke();
      }

      // 4. 手臂 (Arms)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 超人飞行姿态手臂 ===
          // 右手：握拳向前伸直 (向上)
          // 左手：贴紧身体或微弯

          // 前手 (Right Arm - in this context, pointing 'up' relative to rotated body)
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(0, neckY - 40); // 笔直向前
          ctx.stroke();

          // 拳头
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.arc(0, neckY - 45, 8, 0, Math.PI * 2);
          ctx.fill();

          // 后手 (Left Arm - 稍微弯曲在身侧)
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(10, neckY + 20);
          ctx.stroke();

      } else if (entity.isLoser) {
           ctx.beginPath();
           ctx.moveTo(0, neckY);
           ctx.lineTo(-12, neckY + 30);
           ctx.moveTo(0, neckY);
           ctx.lineTo(12, neckY + 30);
           ctx.stroke();
      } else if (entity.isAttacking) {
          // 攻击手臂
          const punchExtend = 25 + (entity.attackFrame * 4);
          ctx.beginPath();
          // 后手护脸
          ctx.moveTo(0, neckY);
          ctx.lineTo(-15, neckY + 15);
          // 前手出拳 (水平)
          ctx.moveTo(0, neckY);
          ctx.lineTo(punchExtend, neckY);
          ctx.stroke();

          // 拳头特效
          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 15;
          ctx.fillRect(punchExtend, neckY - 10, 30, 20); // 更大的拳风
          ctx.restore();
      } else if (entity.isCrouching) {
          // 下蹲防御
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(18, neckY + 15); // 手臂向下
          ctx.moveTo(0, neckY);
          ctx.lineTo(12, neckY + 15);
          ctx.stroke();
      } else {
          // 战斗站姿 (Guard)
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(20, neckY + 10); // 前臂
          ctx.lineTo(25, neckY - 10); // 举起

          ctx.moveTo(0, neckY);
          ctx.lineTo(10, neckY + 20); // 后臂自然下垂一点
          ctx.stroke();
      }

      // 5. 皇冠 (仅胜利者)
      if (entity.isWinner) {
          ctx.save();
          // 皇冠需要反向旋转回来一点，或者保持在头顶
          // 如果是超人飞，皇冠应该跟着头走，不需要额外处理

          ctx.fillStyle = '#FFD700';
          ctx.strokeStyle = '#DAA520';
          ctx.lineWidth = 2;
          ctx.translate(0, headY - 28); // 头顶上方

          // 简单的皇冠形状
          ctx.beginPath();
          ctx.moveTo(-15, 0);
          ctx.lineTo(-15, -15);
          ctx.lineTo(-5, -5);
          ctx.lineTo(0, -20);
          ctx.lineTo(5, -5);
          ctx.lineTo(15, -15);
          ctx.lineTo(15, 0);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();
          ctx.restore();
      }

      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清空
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 震屏
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景
    drawBackground(ctx, canvas.width, canvas.height);

    // 绘制粒子
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;

        ctx.beginPath();
        if (p.gravity && p.gravity < 0.1) {
            // 纸带
            ctx.save();
            ctx.translate(p.pos.x, p.pos.y);
            ctx.rotate(frameRef.current * 0.1 + parseFloat(p.id)); 
            ctx.fillRect(-p.size, -p.size/2, p.size*2, p.size);
            ctx.restore();
        } else {
            // 圆形粒子
            ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 1.0;
    });

    // 绘制实体
    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode } from '../types';
import { playJumpSound, playAttackSound, playHitSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧，蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // P2/CPU (右侧，黄)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15', // 黄色 Yellow-400
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2,
              gravity: 0.5 
          });
      }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];

      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { 
            x: (Math.random() - 0.5) * 2, 
            y: Math.random() * 2 + 1
          },
          life: 200,
          maxLife: 200,
          color: color,
          size: Math.random() * 4 + 3,
          gravity: 0.02 
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // --- 实体更新 ---
    entitiesRef.current.forEach(entity => {
      // 全员应用重力（除了失败者可能已经掉出去了，但为了物理一致性还是加上，反正会掉穿地板）
      entity.vel.y += GRAVITY;

      if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 地面碰撞检测 (胜利者现在也需要站在地面上)
      if (!entity.isLoser) { 
        if (entity.pos.y >= GROUND_Y) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
        } else {
            entity.isGrounded = false;
        }

        // 边界检测
        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      // === 胜利逻辑 ===
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;

              // 胜利者减速
              entity.vel.x *= 0.9;

              // 撒花效果
              if (frameRef.current % 3 === 0) { 
                  spawnConfetti(canvas.width);
              }
              // 不 return，让胜利者继续执行物理逻辑（如落地）
          }
          // 不再处理输入，只处理物理
          return;
      }

      // === 战斗逻辑 ===
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                const dist = p1.pos.x - entity.pos.x;
                const absDist = Math.abs(dist);
                const danger = p1.isAttacking && absDist < ATTACK_RANGE + 20;

                if (danger && Math.random() < 0.6) {
                    crouch = true;
                } else {
                    if (absDist > ATTACK_RANGE - 10) {
                        dist > 0 ? moveRight = true : moveLeft = true;
                    } else if (absDist < 40) {
                        dist > 0 ? moveLeft = true : moveRight = true;
                    }
                    if (absDist < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                        if (Math.random() < 0.05) attack = true;
                    }
                    if (entity.isGrounded && Math.random() < 0.01) jump = true;
                }
                entity.facingRight = dist > 0;
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;

      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }

      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      if (attack && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;
          playAttackSound(); 

          const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
          const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

          entitiesRef.current.forEach(target => {
              if (target !== entity && !target.isDead) {
                  const dx = target.pos.x - hitX;
                  const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                  const dy = targetCenterY - hitY;

                  if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                      if (!entity.isCrouching && target.isCrouching) {
                          spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                          return; 
                      }

                      target.health -= ATTACK_DAMAGE;
                      target.vel.x = entity.facingRight ? 10 : -10;
                      target.vel.y = -5;

                      shakeRef.current = 8;
                      spawnParticles(hitX, hitY, target.color, 8);
                      playHitSound();

                      if (target.health <= 0) {
                          target.health = 0;
                          target.isDead = true;
                          target.isLoser = true;
                          entity.isWinner = true;
                          statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                          setGameState(GameState.VICTORY_ANIMATION);
                          setTimeout(() => {
                              setGameState(GameState.GAME_OVER);
                          }, 5000);
                      }
                  }
              }
          });
      }
    });

    // --- 粒子更新 ---
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        const g = p.gravity !== undefined ? p.gravity : 0.5;
        p.vel.y += g;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  // === 绘制动态背景 ===
  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      // 1. 深色基础
      ctx.fillStyle = '#0f172a'; // Slate-900
      ctx.fillRect(0, 0, width, height);

      // 2. 动态网格地板
      const time = frameRef.current;
      const gridSpeed = 2;
      const offset = (time * gridSpeed) % 100;

      ctx.strokeStyle = '#334155'; // Slate-700
      ctx.lineWidth = 1;

      // 垂直线 (移动)
      ctx.beginPath();
      for (let x = -offset; x < width; x += 100) {
          ctx.moveTo(x, GROUND_Y);
          ctx.lineTo(x, height);
      }
      ctx.stroke();

      // 水平线 (透视效果模拟 - 实际上这里用平行线简单处理)
      ctx.beginPath();
      for (let y = GROUND_Y; y < height; y += 50) {
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
      }
      ctx.stroke();

      // 3. 背景装饰柱动态发光
      const pulse = Math.sin(time * 0.05) * 0.5 + 0.5; // 0~1
      const pillarColor = `rgba(50, 60, 80, ${0.5 + pulse * 0.2})`;

      ctx.fillStyle = pillarColor;
      ctx.fillRect(100, GROUND_Y - 300, 80, 300);
      ctx.fillRect(width - 180, GROUND_Y - 300, 80, 300);

      // 柱子高光线条
      ctx.strokeStyle = `rgba(100, 200, 255, ${0.1 + pulse * 0.2})`;
      ctx.lineWidth = 2;
      ctx.strokeRect(100, GROUND_Y - 300, 80, 300);
      ctx.strokeRect(width - 180, GROUND_Y - 300, 80, 300);

      // 4. 地面分界线
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#000';
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(0, GROUND_Y);
      ctx.lineTo(width, GROUND_Y);
      ctx.stroke();
      ctx.shadowBlur = 0;
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      // 失败者：旋转掉落
      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }

      // 胜利者：不旋转，保持站立

      if (!entity.facingRight) {
          ctx.scale(-1, 1);
      }

      const color = entity.isLoser ? '#64748b' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;

      // === 健全肢体渲染 ===
      // 加粗线条，使用圆角
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // 坐标定义
      let headY = -85;
      let neckY = -70; // 脖子/肩膀中心
      let hipY = -40; // 臀部中心

      if (entity.isCrouching) {
          headY = -55;
          neckY = -40;
          hipY = -25;
      }

      // 1. 身体 (Torso)
      ctx.beginPath();
      ctx.moveTo(0, neckY);
      ctx.lineTo(0, hipY);
      ctx.stroke();

      // 2. 头部 (Head)
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      // 头部稍微大一点
      ctx.arc(renderHeadX, renderHeadY, 15, 0, Math.PI * 2);
      ctx.fill();

      // 3. 腿部 (Legs)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 胜利站姿腿部 (自然站立) ===
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-10, 0); // 左腿
          ctx.moveTo(0, hipY);
          ctx.lineTo(10, 0);  // 右腿
          ctx.stroke();
      } else if (entity.isLoser) {
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, 10);
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, 15);
          ctx.stroke();
      } else if (entity.isCrouching) {
          // 下蹲 M 型腿
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-18, -5); 
          ctx.lineTo(-10, 0);
          ctx.moveTo(0, hipY);
          ctx.lineTo(18, -5);
          ctx.lineTo(10, 0);
          ctx.stroke();
      } else {
          // 跑步动画
          const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
          const runCycle = Math.sin(frameRef.current * 0.4);

          ctx.beginPath();
          if (isRunning) {
              // 跑步时膝盖弯曲
              // 后腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(-15 * Math.cos(runCycle), 0);
              // 前腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(15 * Math.cos(runCycle), 0);
          } else {
              // 站立 (微张)
              ctx.moveTo(0, hipY);
              ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY);
              ctx.lineTo(10, 0);
          }
          ctx.stroke();
      }

      // 4. 手臂 (Arms)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 胜利欢呼姿态 (双手举高) ===
          ctx.beginPath();
          // 左手 V 字举起
          ctx.moveTo(0, neckY);
          ctx.lineTo(-20, neckY - 35);
          // 右手 V 字举起
          ctx.moveTo(0, neckY);
          ctx.lineTo(20, neckY - 35);
          ctx.stroke();
      } else if (entity.isLoser) {
           ctx.beginPath();
           ctx.moveTo(0, neckY);
           ctx.lineTo(-12, neckY + 30);
           ctx.moveTo(0, neckY);
           ctx.lineTo(12, neckY + 30);
           ctx.stroke();
      } else if (entity.isAttacking) {
          // 攻击手臂
          const punchExtend = 25 + (entity.attackFrame * 4);
          ctx.beginPath();
          // 后手护脸
          ctx.moveTo(0, neckY);
          ctx.lineTo(-15, neckY + 15);
          // 前手出拳 (水平)
          ctx.moveTo(0, neckY);
          ctx.lineTo(punchExtend, neckY);
          ctx.stroke();

          // 拳头特效
          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 15;
          ctx.fillRect(punchExtend, neckY - 10, 30, 20); // 更大的拳风
          ctx.restore();
      } else if (entity.isCrouching) {
          // 下蹲防御
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(18, neckY + 15); // 手臂向下
          ctx.moveTo(0, neckY);
          ctx.lineTo(12, neckY + 15);
          ctx.stroke();
      } else {
          // 战斗站姿 (Guard)
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(20, neckY + 10); // 前臂
          ctx.lineTo(25, neckY - 10); // 举起

          ctx.moveTo(0, neckY);
          ctx.lineTo(10, neckY + 20); // 后臂自然下垂一点
          ctx.stroke();
      }

      // 5. 皇冠 (仅胜利者)
      if (entity.isWinner) {
          ctx.save();

          ctx.fillStyle = '#FFD700';
          ctx.strokeStyle = '#DAA520';
          ctx.lineWidth = 2;
          ctx.translate(0, headY - 28); // 头顶上方

          // 简单的皇冠形状
          ctx.beginPath();
          ctx.moveTo(-15, 0);
          ctx.lineTo(-15, -15);
          ctx.lineTo(-5, -5);
          ctx.lineTo(0, -20);
          ctx.lineTo(5, -5);
          ctx.lineTo(15, -15);
          ctx.lineTo(15, 0);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();
          ctx.restore();
      }

      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清空
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 震屏
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景
    drawBackground(ctx, canvas.width, canvas.height);

    // 绘制粒子
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;

        ctx.beginPath();
        if (p.gravity && p.gravity < 0.1) {
            // 纸带
            ctx.save();
            ctx.translate(p.pos.x, p.pos.y);
            ctx.rotate(frameRef.current * 0.1 + parseFloat(p.id)); 
            ctx.fillRect(-p.size, -p.size/2, p.size*2, p.size);
            ctx.restore();
        } else {
            // 圆形粒子
            ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 1.0;
    });

    // 绘制实体
    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode } from '../types';
import { playJumpSound, playAttackSound, playHitSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);
  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧，蓝)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    // P2/CPU (右侧，黄)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15', // 黄色 Yellow-400
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: 30 + Math.random() * 20,
              maxLife: 50,
              color: color,
              size: Math.random() * 5 + 2,
              gravity: 0.5 
          });
      }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];

      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { 
            x: (Math.random() - 0.5) * 2, 
            y: Math.random() * 2 + 1
          },
          life: 200,
          maxLife: 200,
          color: color,
          size: Math.random() * 4 + 3,
          gravity: 0.02 
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // --- 实体更新 ---
    entitiesRef.current.forEach(entity => {
      // === 胜利逻辑 (优先处理飞行) ===
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;

              // 飞行目标：屏幕水平居中，垂直 1/3 处
              const targetX = canvas.width / 2;
              const targetY = canvas.height / 3;

              // 平滑插值移动 (Lerp)
              entity.pos.x += (targetX - entity.pos.x) * 0.05;
              entity.pos.y += (targetY - entity.pos.y) * 0.05;

              // 空中悬停呼吸感 (上下浮动)
              entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;

              // 消除速度，由位置直接控制
              entity.vel.x = 0;
              entity.vel.y = 0;

              // 持续撒花
              if (frameRef.current % 3 === 0) { 
                  spawnConfetti(canvas.width);
              }

              // 胜利者跳过常规物理更新
              return;
          } else {
             // 失败者继续受重力影响，并且无法控制
             // 继续向下执行常规物理逻辑，但不处理输入
          }
      }

      // === 常规物理逻辑 ===
      entity.vel.y += GRAVITY;

      if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 地面碰撞检测
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          } else {
            // 失败者可能会被打飞出屏幕，或者在地面弹一下
             if (entity.pos.y > GROUND_Y + 100) {
                 // 既然已经输了，掉下去就掉下去吧，这里可以不做强制吸附
             }
          }
      } else {
          entity.isGrounded = false;
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      // 如果处于胜利动画阶段且不是胜利者（即失败者），不再处理输入和攻击
      if (gameState === GameState.VICTORY_ANIMATION) return;

      // === 战斗与输入逻辑 ===
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                const dist = p1.pos.x - entity.pos.x;
                const absDist = Math.abs(dist);
                const danger = p1.isAttacking && absDist < ATTACK_RANGE + 20;

                if (danger && Math.random() < 0.6) {
                    crouch = true;
                } else {
                    if (absDist > ATTACK_RANGE - 10) {
                        dist > 0 ? moveRight = true : moveLeft = true;
                    } else if (absDist < 40) {
                        dist > 0 ? moveLeft = true : moveRight = true;
                    }
                    if (absDist < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                        if (Math.random() < 0.05) attack = true;
                    }
                    if (entity.isGrounded && Math.random() < 0.01) jump = true;
                }
                entity.facingRight = dist > 0;
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;

      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }

      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      if (attack && entity.attackCooldown === 0) {
          entity.isAttacking = true;
          entity.attackCooldown = ATTACK_COOLDOWN;
          playAttackSound(); 

          const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
          const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

          entitiesRef.current.forEach(target => {
              if (target !== entity && !target.isDead) {
                  const dx = target.pos.x - hitX;
                  const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                  const dy = targetCenterY - hitY;

                  if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                      if (!entity.isCrouching && target.isCrouching) {
                          spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                          return; 
                      }

                      target.health -= ATTACK_DAMAGE;
                      target.vel.x = entity.facingRight ? 10 : -10;
                      target.vel.y = -5;

                      shakeRef.current = 8;
                      spawnParticles(hitX, hitY, target.color, 8);
                      playHitSound();

                      if (target.health <= 0) {
                          target.health = 0;
                          target.isDead = true;
                          target.isLoser = true;
                          entity.isWinner = true;
                          statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                          setGameState(GameState.VICTORY_ANIMATION);
                          setTimeout(() => {
                              setGameState(GameState.GAME_OVER);
                          }, 5000);
                      }
                  }
              }
          });
      }
    });

    // --- 粒子更新 ---
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        const g = p.gravity !== undefined ? p.gravity : 0.5;
        p.vel.y += g;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  // === 绘制动态背景 ===
  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      // 1. 深色基础
      ctx.fillStyle = '#0f172a'; // Slate-900
      ctx.fillRect(0, 0, width, height);

      // 2. 动态网格地板
      const time = frameRef.current;
      const gridSpeed = 2;
      const offset = (time * gridSpeed) % 100;

      ctx.strokeStyle = '#334155'; // Slate-700
      ctx.lineWidth = 1;

      // 垂直线 (移动)
      ctx.beginPath();
      for (let x = -offset; x < width; x += 100) {
          ctx.moveTo(x, GROUND_Y);
          ctx.lineTo(x, height);
      }
      ctx.stroke();

      // 水平线 (透视效果模拟 - 实际上这里用平行线简单处理)
      ctx.beginPath();
      for (let y = GROUND_Y; y < height; y += 50) {
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
      }
      ctx.stroke();

      // 3. 背景装饰柱动态发光
      const pulse = Math.sin(time * 0.05) * 0.5 + 0.5; // 0~1
      const pillarColor = `rgba(50, 60, 80, ${0.5 + pulse * 0.2})`;

      ctx.fillStyle = pillarColor;
      ctx.fillRect(100, GROUND_Y - 300, 80, 300);
      ctx.fillRect(width - 180, GROUND_Y - 300, 80, 300);

      // 柱子高光线条
      ctx.strokeStyle = `rgba(100, 200, 255, ${0.1 + pulse * 0.2})`;
      ctx.lineWidth = 2;
      ctx.strokeRect(100, GROUND_Y - 300, 80, 300);
      ctx.strokeRect(width - 180, GROUND_Y - 300, 80, 300);

      // 4. 地面分界线
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#000';
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(0, GROUND_Y);
      ctx.lineTo(width, GROUND_Y);
      ctx.stroke();
      ctx.shadowBlur = 0;
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      // 失败者：旋转掉落
      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }

      if (!entity.facingRight) {
          ctx.scale(-1, 1);
      }

      const color = entity.isLoser ? '#64748b' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;

      // === 健全肢体渲染 ===
      // 加粗线条，使用圆角
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // 坐标定义
      let headY = -85;
      let neckY = -70; // 脖子/肩膀中心
      let hipY = -40; // 臀部中心

      if (entity.isCrouching) {
          headY = -55;
          neckY = -40;
          hipY = -25;
      }

      // 1. 身体 (Torso)
      ctx.beginPath();
      ctx.moveTo(0, neckY);
      ctx.lineTo(0, hipY);
      ctx.stroke();

      // 2. 头部 (Head)
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      // 头部稍微大一点
      ctx.arc(renderHeadX, renderHeadY, 15, 0, Math.PI * 2);
      ctx.fill();

      // 3. 腿部 (Legs)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 胜利飞行腿部姿态 ===
          // 双腿自然下垂，稍微并拢
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, hipY + 45); // 腿稍微长一点，伸直
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, hipY + 45);  
          ctx.stroke();
      } else if (entity.isLoser) {
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-5, 10);
          ctx.moveTo(0, hipY);
          ctx.lineTo(5, 15);
          ctx.stroke();
      } else if (entity.isCrouching) {
          // 下蹲 M 型腿
          ctx.beginPath();
          ctx.moveTo(0, hipY);
          ctx.lineTo(-18, -5); 
          ctx.lineTo(-10, 0);
          ctx.moveTo(0, hipY);
          ctx.lineTo(18, -5);
          ctx.lineTo(10, 0);
          ctx.stroke();
      } else {
          // 跑步动画
          const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
          const runCycle = Math.sin(frameRef.current * 0.4);

          ctx.beginPath();
          if (isRunning) {
              // 跑步时膝盖弯曲
              // 后腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(-15 * Math.cos(runCycle), 0);
              // 前腿
              ctx.moveTo(0, hipY);
              ctx.lineTo(15 * Math.cos(runCycle), 0);
          } else {
              // 站立 (微张)
              ctx.moveTo(0, hipY);
              ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY);
              ctx.lineTo(10, 0);
          }
          ctx.stroke();
      }

      // 4. 手臂 (Arms)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          // === 胜利飞行欢呼姿态 (双手呈 V 字高举) ===
          ctx.beginPath();
          // 左臂高举
          ctx.moveTo(0, neckY);
          ctx.lineTo(-25, neckY - 40); 
          // 右臂高举
          ctx.moveTo(0, neckY);
          ctx.lineTo(25, neckY - 40);
          ctx.stroke();

          // 绘制手部（拳头或手掌），增强视觉重心
          ctx.save();
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.arc(-25, neckY - 40, 6, 0, Math.PI * 2);
          ctx.arc(25, neckY - 40, 6, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();

      } else if (entity.isLoser) {
           ctx.beginPath();
           ctx.moveTo(0, neckY);
           ctx.lineTo(-12, neckY + 30);
           ctx.moveTo(0, neckY);
           ctx.lineTo(12, neckY + 30);
           ctx.stroke();
      } else if (entity.isAttacking) {
          // 攻击手臂
          const punchExtend = 25 + (entity.attackFrame * 4);
          ctx.beginPath();
          // 后手护脸
          ctx.moveTo(0, neckY);
          ctx.lineTo(-15, neckY + 15);
          // 前手出拳 (水平)
          ctx.moveTo(0, neckY);
          ctx.lineTo(punchExtend, neckY);
          ctx.stroke();

          // 拳头特效
          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 15;
          ctx.fillRect(punchExtend, neckY - 10, 30, 20); // 更大的拳风
          ctx.restore();
      } else if (entity.isCrouching) {
          // 下蹲防御
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(18, neckY + 15); // 手臂向下
          ctx.moveTo(0, neckY);
          ctx.lineTo(12, neckY + 15);
          ctx.stroke();
      } else {
          // 战斗站姿 (Guard)
          ctx.beginPath();
          ctx.moveTo(0, neckY);
          ctx.lineTo(20, neckY + 10); // 前臂
          ctx.lineTo(25, neckY - 10); // 举起

          ctx.moveTo(0, neckY);
          ctx.lineTo(10, neckY + 20); // 后臂自然下垂一点
          ctx.stroke();
      }

      // 5. 皇冠 (仅胜利者)
      if (entity.isWinner) {
          ctx.save();

          ctx.fillStyle = '#FFD700';
          ctx.strokeStyle = '#DAA520';
          ctx.lineWidth = 2;
          ctx.translate(0, headY - 28); // 头顶上方

          // 皇冠
          ctx.beginPath();
          ctx.moveTo(-15, 0);
          ctx.lineTo(-15, -15);
          ctx.lineTo(-5, -5);
          ctx.lineTo(0, -20);
          ctx.lineTo(5, -5);
          ctx.lineTo(15, -15);
          ctx.lineTo(15, 0);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          // 皇冠闪光
          if (frameRef.current % 20 < 10) {
             ctx.fillStyle = '#FFF';
             ctx.fillRect(-10, -10, 3, 3);
             ctx.fillRect(8, -8, 3, 3);
          }

          ctx.restore();
      }

      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 清空
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 震屏
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);

    // 绘制背景
    drawBackground(ctx, canvas.width, canvas.height);

    // 绘制粒子
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;

        ctx.beginPath();
        if (p.gravity && p.gravity < 0.1) {
            // 纸带
            ctx.save();
            ctx.translate(p.pos.x, p.pos.y);
            ctx.rotate(frameRef.current * 0.1 + parseFloat(p.id)); 
            ctx.fillRect(-p.size, -p.size/2, p.size*2, p.size);
            ctx.restore();
        } else {
            // 圆形粒子
            ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 1.0;
    });

    // 绘制实体
    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

