let audioCtx: AudioContext | null = null;

// 获取或初始化 AudioContext
const getContext = () => {
    if (!audioCtx) {
        audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtx;
};

export const playJumpSound = () => {
    try {
        const ctx = getContext();
        if (ctx.state === 'suspended') ctx.resume();

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.type = 'sine';
        osc.frequency.setValueAtTime(200, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(500, ctx.currentTime + 0.15);

        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.15);

        osc.start();
        osc.stop(ctx.currentTime + 0.15);
    } catch (e) { }
};

export const playAttackSound = () => {
    try {
        const ctx = getContext();
        if (ctx.state === 'suspended') ctx.resume();

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.type = 'triangle';
        osc.frequency.setValueAtTime(400, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);

        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.1);

        osc.start();
        osc.stop(ctx.currentTime + 0.1);
    } catch (e) { }
};

export const playHitSound = () => {
    try {
        const ctx = getContext();
        if (ctx.state === 'suspended') ctx.resume();

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.type = 'square';
        osc.frequency.setValueAtTime(150, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(50, ctx.currentTime + 0.1);

        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

        osc.start();
        osc.stop(ctx.currentTime + 0.1);
    } catch (e) { }
};

export const playShootSound = () => {
    try {
        const ctx = getContext();
        if (ctx.state === 'suspended') ctx.resume();

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const filter = ctx.createBiquadFilter();

        osc.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        // 锯齿波模拟枪声
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.1);

        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(2000, ctx.currentTime);
        filter.frequency.linearRampToValueAtTime(500, ctx.currentTime + 0.1);

        gain.gain.setValueAtTime(0.2, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);

        osc.start();
        osc.stop(ctx.currentTime + 0.15);
    } catch (e) { }
};

export const playExplodeSound = () => {
    try {
        const ctx = getContext();
        if (ctx.state === 'suspended') ctx.resume();

        const bufferSize = ctx.sampleRate * 0.5; // 0.5秒
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);

        // 白噪声
        for (let i = 0; i < bufferSize; i++) {
            data[i] = Math.random() * 2 - 1;
        }

        const noise = ctx.createBufferSource();
        noise.buffer = buffer;

        const gain = ctx.createGain();
        // 衰减
        gain.gain.setValueAtTime(0.5, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

        noise.connect(gain);
        gain.connect(ctx.destination);
        noise.start();
    } catch (e) { }
};

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 ===
const GRAVITY = 0.5;
const FRICTION = 0.90;
const MOVE_SPEED = 0.8;
const JUMP_FORCE = -14;
const GROUND_Y = 550;
const ATTACK_COOLDOWN = 40;
const ATTACK_RANGE = 90;
const ATTACK_DAMAGE = 10;
const WEAPON_SPAWN_RATE = 0.002; // 每帧 0.2% 概率掉落

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const bgThemeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];
    bgThemeRef.current = Math.floor(Math.random() * 4);

    // P1
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null
    });

    // P2/CPU
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 200, y: GROUND_Y }, vel: { x: 0, y: 0 },
      width: 40, height: 80, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (30 + Math.random() * 20) * lifeMultiplier,
              maxLife: 50 * lifeMultiplier,
              color: color,
              size: Math.random() * 5 + 2,
              gravity: 0.5 
          });
      }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];

      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      const type: WeaponType = Math.random() > 0.5 ? 'pistol' : 'bomb';
      fallingItemsRef.current.push({
          id: Math.random().toString(),
          type,
          pos: { x: 50 + Math.random() * (canvasWidth - 100), y: -50 },
          vel: { x: 0, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && Math.random() < WEAPON_SPAWN_RATE) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        if (!item.onGround) {
            item.vel.y += 0.2; // 较轻的重力，像降落伞
            if (item.vel.y > 5) item.vel.y = 5;
            item.pos.y += item.vel.y;
            if (item.pos.y >= GROUND_Y - item.height) {
                item.pos.y = GROUND_Y - item.height;
                item.onGround = true;
                item.vel.y = 0;
            }
        }
    });

    // === 2. 投射物逻辑 ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        if (proj.type === 'bomb') {
            proj.vel.y += GRAVITY; // 炸弹受重力
            // 落地爆炸
            if (proj.pos.y >= GROUND_Y) {
                proj.active = false;
                shakeRef.current = 20;
                playExplodeSound();
                spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 30, 15, 2); // 爆炸粒子

                // 爆炸范围伤害
                entitiesRef.current.forEach(target => {
                    if (!target.isDead) {
                        const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                        if (dist < 150) { // 爆炸半径
                            target.health = 0; // 一招致命
                            target.isDead = true;
                            target.isLoser = true;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) {
                                winner.isWinner = true;
                                statsRef.current.winner = winner.id === 'p1' ? 'P1' : 'P2';
                                setGameState(GameState.VICTORY_ANIMATION);
                                setTimeout(() => setGameState(GameState.GAME_OVER), 5000);
                            }
                        }
                    }
                });
            }
        } else {
            // 子弹
            if (proj.pos.x < 0 || proj.pos.x > canvas.width) proj.active = false;

            // 子弹碰撞检测
            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    // 简单的矩形碰撞
                    if (proj.pos.x > target.pos.x - 20 && proj.pos.x < target.pos.x + 20 &&
                        proj.pos.y > target.pos.y - 80 && proj.pos.y < target.pos.y) {

                        proj.active = false;
                        target.health = 0; // 一招致命
                        target.isDead = true;
                        target.isLoser = true;
                        shakeRef.current = 10;
                        playHitSound();
                        spawnParticles(target.pos.x, target.pos.y - 40, '#ff0000', 20, 10);

                        const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                        if (winner) {
                            winner.isWinner = true;
                            statsRef.current.winner = winner.id === 'p1' ? 'P1' : 'P2';
                            setGameState(GameState.VICTORY_ANIMATION);
                            setTimeout(() => setGameState(GameState.GAME_OVER), 5000);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 胜利飞行逻辑
      if (gameState === GameState.VICTORY_ANIMATION) {
          if (entity.isWinner) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
              entity.isCrouching = false;
              const targetX = canvas.width / 2;
              const targetY = canvas.height / 3;
              entity.pos.x += (targetX - entity.pos.x) * 0.05;
              entity.pos.y += (targetY - entity.pos.y) * 0.05;
              entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
              entity.vel.x = 0; entity.vel.y = 0;
              if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
              return;
          }
      }

      // 拾取武器逻辑
      if (!entity.isDead && !entity.heldWeapon) {
          const itemIndex = fallingItemsRef.current.findIndex(item => {
              const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
              const dy = Math.abs((entity.pos.y - 40) - (item.pos.y + item.height/2));
              return dx < 40 && dy < 60;
          });

          if (itemIndex !== -1) {
              entity.heldWeapon = fallingItemsRef.current[itemIndex].type;
              fallingItemsRef.current.splice(itemIndex, 1);
              // 拾取音效（暂时用 Jump 代替）
              playJumpSound();
          }
      }

      // 常规物理
      entity.vel.y += GRAVITY;
      if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.5 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }
      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      } else {
          entity.isGrounded = false;
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 20) entity.pos.x = 20;
        if (entity.pos.x > canvas.width - 20) entity.pos.x = canvas.width - 20;
      }

      if (gameState === GameState.VICTORY_ANIMATION) return;

      // 攻击冷却
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 20) {
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                // AI 优先去捡武器
                let targetX = p1.pos.x;
                let hasItemTarget = false;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    // 寻找最近的武器
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            hasItemTarget = true;
                        }
                    });
                }

                const dist = targetX - entity.pos.x;
                const absDist = Math.abs(dist);

                if (hasItemTarget) {
                    // 冲向武器
                    dist > 0 ? moveRight = true : moveLeft = true;
                    if (entity.isGrounded && Math.abs(dist) > 50 && Math.random() < 0.05) jump = true;
                    entity.facingRight = dist > 0;
                } else {
                    // 战斗逻辑
                    const distToP1 = p1.pos.x - entity.pos.x;
                    const absDistToP1 = Math.abs(distToP1);
                    const isP1Attacking = p1.isAttacking && absDistToP1 < ATTACK_RANGE + 40;

                    // 有武器就尝试攻击
                    if (entity.heldWeapon) {
                        entity.facingRight = distToP1 > 0;
                        if (entity.heldWeapon === 'pistol') {
                            // 枪：只要面向且高度差不多就射击
                            if (absDistToP1 < 600 && Math.abs(p1.pos.y - entity.pos.y) < 50) {
                                attack = true;
                            }
                        } else {
                            // 炸弹：距离适中扔炸弹
                            if (absDistToP1 < 400 && absDistToP1 > 100) {
                                attack = true;
                            } else if (absDistToP1 < 100) {
                                // 太近了后退
                                distToP1 > 0 ? moveLeft = true : moveRight = true;
                            } else {
                                distToP1 > 0 ? moveRight = true : moveLeft = true;
                            }
                        }
                    } else {
                        // 无武器常规战斗
                        if (isP1Attacking) {
                            if (!p1.isCrouching) {
                                if (Math.random() < 0.9) crouch = true;
                            } else {
                                if (entity.isGrounded && Math.random() < 0.4) jump = true;
                            }
                        } else {
                            if (frameRef.current % 120 === 0 && Math.random() < 0.3) crouch = true;
                        }

                        if (!crouch) {
                            if (absDistToP1 > ATTACK_RANGE - 10) {
                                distToP1 > 0 ? moveRight = true : moveLeft = true;
                            } else if (absDistToP1 < 50) {
                                distToP1 > 0 ? moveLeft = true : moveRight = true;
                            }

                            if (absDistToP1 < ATTACK_RANGE + 10 && entity.attackCooldown === 0) {
                                if (Math.random() < 0.3) crouch = true;
                                if (Math.random() < 0.08) attack = true;
                            }
                            if (entity.isGrounded && Math.random() < 0.005) jump = true;
                        }
                        entity.facingRight = distToP1 > 0;
                    }
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;

          if (entity.heldWeapon) {
              // == 特殊武器攻击 ==
              if (entity.heldWeapon === 'pistol') {
                  playShootSound();
                  projectilesRef.current.push({
                      id: Math.random().toString(),
                      type: 'pistol',
                      pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                      vel: { x: entity.facingRight ? 20 : -20, y: 0 },
                      ownerId: entity.id,
                      width: 10, height: 4, active: true
                  });
              } else if (entity.heldWeapon === 'bomb') {
                  // 投掷炸弹
                  projectilesRef.current.push({
                      id: Math.random().toString(),
                      type: 'bomb',
                      pos: { x: entity.pos.x, y: entity.pos.y - 80 },
                      vel: { x: entity.facingRight ? 10 : -10, y: -10 },
                      ownerId: entity.id,
                      width: 20, height: 20, active: true
                  });
              }
              // 武器是一次性的！使用后丢弃
              entity.heldWeapon = null;
          } else {
              // == 普通近战攻击 ==
              entity.isAttacking = true;
              playAttackSound(); 
              const hitX = entity.facingRight ? entity.pos.x + 60 : entity.pos.x - 60;
              const hitY = entity.isCrouching ? entity.pos.y - 30 : entity.pos.y - 60;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dx = target.pos.x - hitX;
                      const targetCenterY = target.isCrouching ? target.pos.y - 25 : target.pos.y - 50;
                      const dy = targetCenterY - hitY;

                      if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= ATTACK_DAMAGE;
                          target.vel.x = entity.facingRight ? 10 : -10;
                          target.vel.y = -5;
                          shakeRef.current = 8;
                          spawnParticles(hitX, hitY, target.color, 8);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              entity.isWinner = true;
                              statsRef.current.winner = entity.id === 'p1' ? 'P1' : 'P2';
                              setGameState(GameState.VICTORY_ANIMATION);
                              setTimeout(() => setGameState(GameState.GAME_OVER), 5000);
                          }
                      }
                  }
              });
          }
      }
    });

    // 粒子更新
    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        const g = p.gravity !== undefined ? p.gravity : 0.5;
        p.vel.y += g;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  // === 绘制动态背景 ===
  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      const theme = bgThemeRef.current;
      const time = frameRef.current;

      if (theme === 0) {
          const grd = ctx.createLinearGradient(0, 0, 0, height);
          grd.addColorStop(0, "#2a0845");
          grd.addColorStop(0.6, "#6441A5");
          grd.addColorStop(1, "#feac5e");
          ctx.fillStyle = grd;
          ctx.fillRect(0,0,width,height);
          ctx.fillStyle = '#ff7e5f';
          ctx.beginPath();
          ctx.arc(width/2, GROUND_Y, 200, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = "rgba(255,255,255,0.1)";
          ctx.beginPath();
          ctx.arc(width * 0.2 + Math.sin(time*0.005)*50, 100, 60, 0, Math.PI*2);
          ctx.arc(width * 0.25 + Math.sin(time*0.005)*50, 120, 50, 0, Math.PI*2);
          ctx.fill();
      } else if (theme === 1) {
          ctx.fillStyle = '#020205';
          ctx.fillRect(0, 0, width, height);
          for(let i=0; i<50; i++) {
              const starX = (i * 137 + time * 0.1) % width;
              const starY = (i * 59) % GROUND_Y;
              const brightness = Math.abs(Math.sin(time * 0.05 + i));
              ctx.fillStyle = `rgba(255,255,255,${brightness})`;
              ctx.fillRect(starX, starY, 2, 2);
          }
           ctx.fillStyle = '#1f2937';
           ctx.fillRect(0, GROUND_Y, width, height - GROUND_Y);
      } else if (theme === 2) {
          const grd = ctx.createLinearGradient(0, 0, 0, height);
          grd.addColorStop(0, "#000000");
          grd.addColorStop(1, "#0f3d0f");
          ctx.fillStyle = grd;
          ctx.fillRect(0, 0, width, height);
          for(let i=0; i<15; i++) {
               const fx = (Math.sin(i + time * 0.01) * width/2 + width/2);
               const fy = (Math.cos(i + time * 0.02) * 200 + GROUND_Y - 200);
               ctx.fillStyle = `rgba(200, 255, 100, ${Math.abs(Math.sin(time * 0.1 + i))})`;
               ctx.fillRect(fx, fy, 3, 3);
          }
      } else {
          ctx.fillStyle = '#0f172a'; 
          ctx.fillRect(0, 0, width, height);
          const pulse = Math.sin(time * 0.05) * 0.5 + 0.5;
          ctx.fillStyle = `rgba(50, 60, 80, ${0.5 + pulse * 0.2})`;
          ctx.fillRect(100, GROUND_Y - 300, 80, 300);
          ctx.fillRect(width - 180, GROUND_Y - 300, 80, 300);
      }
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#000';
      ctx.strokeStyle = '#fff';
      ctx.globalAlpha = 0.3;
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(0, GROUND_Y);
      ctx.lineTo(width, GROUND_Y);
      ctx.stroke();
      ctx.shadowBlur = 0;
      ctx.globalAlpha = 1.0;
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.05 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.7;
      }
      if (!entity.facingRight) ctx.scale(-1, 1);

      const color = entity.isLoser ? '#64748b' : entity.color;
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 10; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      let headY = -85;
      let neckY = -70; 
      let hipY = -40; 
      if (entity.isCrouching) {
          headY = -55;
          neckY = -40;
          hipY = -25;
      }

      // 身体
      ctx.beginPath();
      ctx.moveTo(0, neckY);
      ctx.lineTo(0, hipY);
      ctx.stroke();

      // 头部
      ctx.beginPath();
      const renderHeadY = entity.isLoser ? headY + 10 : headY;
      const renderHeadX = entity.isLoser ? 10 : 0;
      ctx.arc(renderHeadX, renderHeadY, 15, 0, Math.PI * 2);
      ctx.fill();

      // 腿部
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          ctx.beginPath();
          ctx.moveTo(0, hipY); ctx.lineTo(-5, hipY + 45); 
          ctx.moveTo(0, hipY); ctx.lineTo(5, hipY + 45);  
          ctx.stroke();
      } else if (entity.isLoser) {
          ctx.beginPath();
          ctx.moveTo(0, hipY); ctx.lineTo(-5, 10);
          ctx.moveTo(0, hipY); ctx.lineTo(5, 15);
          ctx.stroke();
      } else if (entity.isCrouching) {
          ctx.beginPath();
          ctx.moveTo(0, hipY); ctx.lineTo(-18, -5); ctx.lineTo(-10, 0);
          ctx.moveTo(0, hipY); ctx.lineTo(18, -5); ctx.lineTo(10, 0);
          ctx.stroke();
      } else {
          const isRunning = Math.abs(entity.vel.x) > 0.1 && entity.isGrounded;
          const runCycle = Math.sin(frameRef.current * 0.4);
          ctx.beginPath();
          if (isRunning) {
              ctx.moveTo(0, hipY); ctx.lineTo(-15 * Math.cos(runCycle), 0);
              ctx.moveTo(0, hipY); ctx.lineTo(15 * Math.cos(runCycle), 0);
          } else {
              ctx.moveTo(0, hipY); ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY); ctx.lineTo(10, 0);
          }
          ctx.stroke();
      }

      // 手臂 (包含持枪/持雷绘制)
      if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
          ctx.beginPath();
          ctx.moveTo(0, neckY); ctx.lineTo(-25, neckY - 40); 
          ctx.moveTo(0, neckY); ctx.lineTo(25, neckY - 40);
          ctx.stroke();
          ctx.save();
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.arc(-25, neckY - 40, 6, 0, Math.PI * 2);
          ctx.arc(25, neckY - 40, 6, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
      } else if (entity.heldWeapon) {
          // 持有武器姿态
          ctx.beginPath();
          // 后手
          ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
          // 前手平举 (持枪/雷)
          ctx.moveTo(0, neckY); ctx.lineTo(25, neckY - 5);
          ctx.stroke();

          // 绘制武器
          ctx.save();
          ctx.translate(30, neckY - 5);
          if (entity.heldWeapon === 'pistol') {
              ctx.fillStyle = '#444';
              ctx.fillRect(-5, -5, 20, 6); // 枪管
              ctx.fillRect(-5, -5, 6, 12);  // 握把
          } else {
              // Bomb
              ctx.fillStyle = '#000';
              ctx.beginPath();
              ctx.arc(0, 0, 10, 0, Math.PI*2);
              ctx.fill();
              // 导火索
              ctx.strokeStyle = '#fff';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(0, -10); ctx.lineTo(5, -15);
              ctx.stroke();
              // 火花
              ctx.fillStyle = '#f00';
              ctx.fillRect(4, -16, 2, 2);
          }
          ctx.restore();

      } else if (entity.isLoser) {
           ctx.beginPath();
           ctx.moveTo(0, neckY); ctx.lineTo(-12, neckY + 30);
           ctx.moveTo(0, neckY); ctx.lineTo(12, neckY + 30);
           ctx.stroke();
      } else if (entity.isAttacking) {
          const punchExtend = 25 + (entity.attackFrame * 4);
          ctx.beginPath();
          ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
          ctx.moveTo(0, neckY); ctx.lineTo(punchExtend, neckY);
          ctx.stroke();
          ctx.save();
          ctx.fillStyle = '#fff';
          ctx.shadowColor = entity.color;
          ctx.shadowBlur = 15;
          ctx.fillRect(punchExtend, neckY - 10, 30, 20); 
          ctx.restore();
      } else if (entity.isCrouching) {
          ctx.beginPath();
          ctx.moveTo(0, neckY); ctx.lineTo(18, neckY + 15); 
          ctx.moveTo(0, neckY); ctx.lineTo(12, neckY + 15);
          ctx.stroke();
      } else {
          ctx.beginPath();
          ctx.moveTo(0, neckY); ctx.lineTo(20, neckY + 10); ctx.lineTo(25, neckY - 10); 
          ctx.moveTo(0, neckY); ctx.lineTo(10, neckY + 20); 
          ctx.stroke();
      }

      // 皇冠
      if (entity.isWinner) {
          ctx.save();
          ctx.fillStyle = '#FFD700'; ctx.strokeStyle = '#DAA520'; ctx.lineWidth = 2;
          ctx.translate(0, headY - 28); 
          ctx.beginPath();
          ctx.moveTo(-15, 0); ctx.lineTo(-15, -15); ctx.lineTo(-5, -5); ctx.lineTo(0, -20);
          ctx.lineTo(5, -5); ctx.lineTo(15, -15); ctx.lineTo(15, 0);
          ctx.closePath(); ctx.fill(); ctx.stroke();
          if (frameRef.current % 20 < 10) {
             ctx.fillStyle = '#FFF'; ctx.fillRect(-10, -10, 3, 3); ctx.fillRect(8, -8, 3, 3);
          }
          ctx.restore();
      }
      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }

    ctx.save();
    ctx.translate(shakeX, shakeY);
    drawBackground(ctx, canvas.width, canvas.height);

    // 绘制掉落物
    fallingItemsRef.current.forEach(item => {
        ctx.save();
        ctx.translate(item.pos.x, item.pos.y);
        // 降落伞绳
        if (!item.onGround) {
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(15, -40);
            ctx.moveTo(30, 0); ctx.lineTo(15, -40);
            ctx.stroke();
            // 伞盖
            ctx.fillStyle = '#ddd';
            ctx.beginPath();
            ctx.arc(15, -40, 25, Math.PI, 0);
            ctx.fill();
        }

        // 箱子
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(0, 0, 30, 30);
        ctx.strokeStyle = '#DAA520';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, 0, 30, 30);

        // 图标
        ctx.font = '20px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(item.type === 'pistol' ? '🔫' : '💣', 15, 22);
        ctx.restore();
    });

    // 绘制投射物
    projectilesRef.current.forEach(p => {
        ctx.save();
        ctx.translate(p.pos.x, p.pos.y);
        if (p.type === 'pistol') {
            ctx.fillStyle = '#FFFF00';
            ctx.shadowBlur = 10;
            ctx.shadowColor = '#FFFF00';
            ctx.fillRect(-5, -2, 10, 4);
        } else {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(0, 0, 10, 0, Math.PI*2);
            ctx.fill();
            // 闪烁红光
            if (frameRef.current % 10 < 5) {
                ctx.fillStyle = '#f00';
                ctx.fillRect(-3, -3, 6, 6);
            }
        }
        ctx.restore();
    });

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        if (p.gravity && p.gravity < 0.1) {
            ctx.save(); ctx.translate(p.pos.x, p.pos.y);
            ctx.rotate(frameRef.current * 0.1 + parseFloat(p.id)); 
            ctx.fillRect(-p.size, -p.size/2, p.size*2, p.size);
            ctx.restore();
        } else {
            ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));
    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useState, useEffect } from 'react';
import GameCanvas from './components/GameCanvas';
import GameUI from './components/GameUI';
import MainMenu from './components/MainMenu';
import GameOver from './components/GameOver';
import { GameState, GameStats, Entity, GameMode } from './types';

function App() {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [gameMode, setGameMode] = useState<GameMode>('PVE');
  const [stats, setStats] = useState<GameStats>({ winner: null, mode: 'PVE', duration: 0 });
  const [players, setPlayers] = useState<Entity[]>([]);

  // 防沉迷统计
  const [sessionGameCount, setSessionGameCount] = useState<number>(0); 
  const [sessionStartTime, setSessionStartTime] = useState<number>(Date.now());

  const handleGameStateChange = (newState: GameState) => {
      setGameState(newState);
      // 如果进入游戏结束状态，当前会话局数+1
      if (newState === GameState.GAME_OVER) {
          setSessionGameCount(prev => prev + 1);
      }
  };

  const handleRestart = () => {
    setGameState(GameState.PLAYING);
  };

  const handleMenu = () => {
    setGameState(GameState.MENU);
  };

  const resetSession = () => {
      setSessionGameCount(0);
      setSessionStartTime(Date.now());
  };

  return (
    <div className="relative w-screen h-screen bg-gray-900 overflow-hidden">
      {/* 游戏渲染层 */}
      <div className="absolute inset-0 z-10">
        <GameCanvas 
          gameState={gameState} 
          setGameState={handleGameStateChange}
          setStats={setStats}
          setPlayers={setPlayers}
          gameMode={gameMode}
        />
      </div>

      {/* 游戏 UI 层 (Playing 状态可见) */}
      {(gameState === GameState.PLAYING || gameState === GameState.VICTORY_ANIMATION) && (
        <div className="absolute inset-0 z-20 pointer-events-none">
          <GameUI stats={stats} players={players} />
        </div>
      )}

      {/* 菜单层 */}
      {gameState === GameState.MENU && (
        <MainMenu setGameState={handleGameStateChange} setGameMode={setGameMode} />
      )}

      {/* 游戏结束层 */}
      {gameState === GameState.GAME_OVER && (
        <GameOver 
          stats={stats} 
          onRestart={handleRestart} 
          onMenu={handleMenu}
          sessionGameCount={sessionGameCount}
          sessionStartTime={sessionStartTime}
          onResetSession={resetSession}
        />
      )}
    </div>
  );
}

export default App;

import React, { useEffect, useState } from 'react';
import { GameState, GameStats } from '../types';
import { getTacticalAnalysis } from '../services/geminiService';

interface GameOverProps {
  stats: GameStats;
  onRestart: () => void;
  onMenu: () => void;
  sessionGameCount: number;
  sessionStartTime: number;
  onResetSession: () => void;
}

const GameOver: React.FC<GameOverProps> = ({ stats, onRestart, onMenu, sessionGameCount, sessionStartTime, onResetSession }) => {
  const [analysis, setAnalysis] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const [cooldown, setCooldown] = useState(0);

  // 防沉迷 / 战术冷却逻辑
  // 触发条件：连续玩3局 OR 游戏时间超过5分钟 (300000ms)
  const timePlayed = Date.now() - sessionStartTime;
  const isTimeLimitReached = timePlayed > 5 * 60 * 1000;
  const isCountLimitReached = sessionGameCount > 0 && sessionGameCount % 3 === 0;

  const isFatigue = isCountLimitReached || isTimeLimitReached;

  useEffect(() => {
    let mounted = true;
    getTacticalAnalysis(stats).then(text => {
      if (mounted) {
        setAnalysis(text);
        setLoading(false);
      }
    });

    // 如果触发防沉迷/冷却，设置倒计时
    if (isFatigue) {
        setCooldown(5);
        const timer = setInterval(() => {
            setCooldown(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }

    return () => { mounted = false; };
  }, [stats, isFatigue]);

  const handleAction = (action: () => void) => {
      if (isFatigue) {
          onResetSession(); // 休息结束，重置会话
      }
      action();
  };

  const p1Won = stats.winner === 'P1';
  const winnerColor = p1Won ? 'text-blue-500' : 'text-yellow-500';
  const winnerBg = p1Won ? 'from-blue-900/40 to-transparent' : 'from-yellow-900/40 to-transparent';

  const winTitles = ["绝对压制", "王者降临", "轻松取胜", "还有谁?", "神之手"];
  const randomTitle = winTitles[Math.floor(Math.random() * winTitles.length)];

  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm animate-fade-in overflow-hidden">

      {/* 动态光束背景 */}
      <div className={`absolute inset-0 bg-gradient-to-tr ${winnerBg} animate-pulse z-0`}></div>

      <div className="relative z-10 w-full max-w-5xl flex flex-col items-center">

        {/* 顶部：巨大的 WINNER 文字 */}
        <div className="relative mb-8">
            <h1 className="text-[10rem] leading-none font-black italic font-comic text-transparent bg-clip-text bg-gradient-to-b from-white to-gray-600 drop-shadow-[0_10px_20px_rgba(0,0,0,0.8)] transform -skew-x-12 scale-y-110">
                WINNER
            </h1>
            <div className={`absolute -bottom-4 right-10 text-6xl font-black ${winnerColor} rotate-[-5deg] drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]`}>
                {stats.winner ? stats.winner : 'DRAW'}
            </div>
        </div>

        {/* 中间内容区域：卡片式布局 */}
        <div className="w-full flex flex-col md:flex-row gap-6 px-8">

            {/* 左侧：胜利姿态 & 数据 */}
            <div className="flex-1 bg-gray-900/80 border border-gray-700 rounded-2xl p-6 flex flex-col items-center justify-center relative overflow-hidden group">
                <div className={`absolute inset-0 bg-gradient-to-br ${winnerBg} opacity-20 group-hover:opacity-40 transition-opacity`}></div>
                <div className="text-9xl mb-4 animate-bounce filter drop-shadow-[0_0_30px_rgba(255,255,255,0.3)]">
                    {p1Won ? '👮‍♂️' : '👷'}
                </div>
                <div className="text-2xl font-bold text-white uppercase tracking-widest mb-2">{randomTitle}</div>
                <div className="font-mono text-gray-400 text-sm bg-black/50 px-3 py-1 rounded-full">
                    K.O. TIME: {Math.floor(stats.duration)}s
                </div>
            </div>

            {/* 右侧：战术分析 */}
            <div className="flex-1 bg-gray-900/80 border border-gray-700 rounded-2xl p-6 relative">
                 <div className="absolute -top-3 left-4 bg-gray-800 text-purple-400 text-xs px-2 py-1 rounded border border-gray-600 font-mono">
                    AI TACTICAL LOG
                 </div>
                 <div className="h-full flex flex-col justify-center">
                    <p className="font-comic text-lg text-gray-200 leading-relaxed typing-cursor min-h-[100px]">
                        {loading ? "正在连接解说席..." : analysis}
                    </p>
                 </div>
            </div>
        </div>

        {/* 底部：操作按钮或冷却界面 */}
        <div className="mt-10 w-full max-w-md">
            {isFatigue && cooldown > 0 ? (
                // 冷却界面
                <div className="w-full bg-red-900/30 border border-red-500/50 rounded-xl p-6 text-center animate-pulse">
                    <h3 className="text-red-400 font-bold text-xl mb-2 flex items-center justify-center gap-2">
                        <span>⚠️</span> SYSTEM OVERHEAT <span>⚠️</span>
                    </h3>
                    <p className="text-gray-400 text-sm mb-4">
                        {isTimeLimitReached ? "游玩时间过长，强制冷却..." : "战斗过热，正在强制冷却..."}
                    </p>
                    <div className="text-4xl font-mono font-black text-white mb-2">{cooldown}</div>
                    <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                        <div 
                           className="h-full bg-red-500 transition-all duration-1000 ease-linear"
                           style={{ width: `${(cooldown/5)*100}%` }}
                        ></div>
                    </div>
                </div>
            ) : (
                // 正常按钮
                <div className="flex gap-4">
                     <button onClick={() => handleAction(onRestart)} className="flex-1 bg-white text-black text-xl font-black py-4 rounded-lg hover:scale-105 hover:bg-yellow-400 transition-all uppercase italic shadow-[0_0_20px_rgba(255,255,255,0.2)]">
                        REMATCH
                    </button>
                    <button onClick={() => handleAction(onMenu)} className="flex-1 bg-transparent border-2 border-gray-600 text-gray-400 font-bold py-4 rounded-lg hover:border-white hover:text-white transition-colors uppercase">
                        MENU
                    </button>
                </div>
            )}
        </div>

        {/* 底部小字 */}
        <div className="mt-6 text-gray-600 font-mono text-xs">
             SESSION: {Math.floor(timePlayed / 1000)}s / 300s | GAMES: {sessionGameCount}
        </div>

      </div>
    </div>
  );
};

export default GameOver;

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  VICTORY_ANIMATION
}

export type GameMode = 'PVE' | 'PVP';

export interface Vector {
  x: number;
  y: number;
}

export type WeaponType = 'pistol' | 'bomb';

export interface Platform {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  isCrouching: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number;
  type: 'player'; 
  playerIndex: number; 
  isWinner?: boolean;
  isLoser?: boolean;
  heldWeapon?: WeaponType | null;
  stunFrames: number; // 新增：受击硬直/击飞状态
}

export interface FallingItem {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  onGround: boolean;
}

export interface Projectile {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  ownerId: string;
  width: number;
  height: number;
  active: boolean;
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  gravity?: number; 
}

export interface GameStats {
  winner: string | null;
  mode: GameMode;
  duration: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (更爽快的战斗参数) ===
const GRAVITY = 0.6; // 更重的重力
const FRICTION = 0.85; // 更滑的地面，方便滑步
const MOVE_SPEED = 1.2; // 更快的移动
const JUMP_FORCE = -16; // 更高的跳跃
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 30; // 更快的攻速
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;
const WEAPON_SPAWN_RATE = 0.003; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } // 顶层平台
];

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, // 空降入场
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keysRef.current.add(e.code);
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier, // 粒子寿命更短，更爽快
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3, // 粒子更大
              gravity: 0.5 
          });
      }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      const type: WeaponType = Math.random() > 0.5 ? 'pistol' : 'bomb';
      fallingItemsRef.current.push({
          id: Math.random().toString(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && Math.random() < WEAPON_SPAWN_RATE) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        // 地面碰撞
        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5; // 弹性
            item.vel.x *= 0.8;
        }

        // 平台碰撞
        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        if (proj.type === 'bomb') {
            proj.vel.y += GRAVITY; 
            // 炸弹碰到地面或平台反弹/爆炸
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;
                shakeRef.current = 25; // 剧烈震动
                playExplodeSound();
                spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                // 爆炸范围击飞
                entitiesRef.current.forEach(target => {
                    if (!target.isDead) {
                        const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                        if (dist < 180) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            // 爆炸冲击波击飞
                            const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                            target.vel.x = Math.cos(angle) * 30;
                            target.vel.y = Math.sin(angle) * 30;

                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                });
            }
        } else {
            // 子弹
            if (proj.pos.x < 0 || proj.pos.x > canvas.width) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    if (proj.pos.x > target.pos.x - 20 && proj.pos.x < target.pos.x + 20 &&
                        proj.pos.y > target.pos.y - 70 && proj.pos.y < target.pos.y) {

                        proj.active = false;
                        target.health = 0; 
                        target.isDead = true;
                        target.isLoser = true;
                        shakeRef.current = 15;
                        playHitSound();
                        spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 30, 12);

                        // 子弹动能击飞
                        target.vel.x = proj.vel.x * 0.8; 
                        target.vel.y = -10;

                        const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                        if (winner) triggerWin(winner.id);
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 胜利飞行
      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead && !entity.heldWeapon) {
          const itemIndex = fallingItemsRef.current.findIndex(item => {
              const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
              const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
              return dx < 50 && dy < 60;
          });

          if (itemIndex !== -1) {
              entity.heldWeapon = fallingItemsRef.current[itemIndex].type;
              fallingItemsRef.current.splice(itemIndex, 1);
              playJumpSound();
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; // 硬直恢复
           entity.vel.x *= 0.95; // 击飞阻力
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; // 尸体滑行
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // === 碰撞检测 ===
      entity.isGrounded = false;

      // 1. 地面
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          } else if (entity.pos.y > GROUND_Y + 500) {
              // 尸体掉出界
          }
      }

      // 2. 平台 (仅当下落时检测，支持单向穿透)
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              // 检测脚部位置
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  // 如果上一帧在平台上方，这一帧在平台下方/内，说明着陆
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      // 蹲下+跳跃可以下台阶 (可选功能，暂时不加简化操作)
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      // 攻击冷却
      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { // 攻击动作加快
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // === AI Update: 懂得利用平台 ===
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                // 优先捡枪
                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    // 找最近的
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; // 负数表示目标在上方

                // 水平移动
                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     // 没武器太近了拉开点距离
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                // 垂直移动 (跳平台)
                if (entity.isGrounded) {
                     // 如果目标在上方较远，或者前方有平台需要跳
                     if (distY < -100) {
                         if (Math.random() < 0.1) jump = true;
                     }
                     // 随机跳跃增加不可预测性
                     if (Math.random() < 0.02) jump = true;
                }

                // 攻击逻辑
                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                if (entity.heldWeapon) {
                    if (entity.heldWeapon === 'pistol') {
                         if (absDistX < 700 && Math.abs(p1.pos.y - entity.pos.y) < 60) attack = true;
                    } else {
                         // Bomb
                         if (absDistX < 400 && absDistX > 100) attack = true;
                    }
                } else {
                    // 近战
                    if (absDistX < ATTACK_RANGE + 10 && Math.abs(p1.pos.y - entity.pos.y) < 50) {
                        if (entity.attackCooldown === 0 && Math.random() < 0.1) attack = true;
                    }
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;

          if (entity.heldWeapon) {
              if (entity.heldWeapon === 'pistol') {
                  playShootSound();
                  // 后坐力
                  entity.vel.x += entity.facingRight ? -8 : 8;
                  entity.vel.y -= 2;

                  projectilesRef.current.push({
                      id: Math.random().toString(),
                      type: 'pistol',
                      pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                      vel: { x: entity.facingRight ? 25 : -25, y: (Math.random()-0.5) * 2 }, // 略微散射
                      ownerId: entity.id,
                      width: 12, height: 4, active: true
                  });
              } else if (entity.heldWeapon === 'bomb') {
                  entity.vel.x += entity.facingRight ? -2 : 2;
                  projectilesRef.current.push({
                      id: Math.random().toString(),
                      type: 'bomb',
                      pos: { x: entity.pos.x, y: entity.pos.y - 80 },
                      vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                      ownerId: entity.id,
                      width: 20, height: 20, active: true
                  });
              }
              entity.heldWeapon = null;
          } else {
              // == 普通近战 (重拳) ==
              entity.isAttacking = true;
              playAttackSound(); 

              // 攻击位移 (突进)
              entity.vel.x = entity.facingRight ? 10 : -10;

              const hitX = entity.facingRight ? entity.pos.x + 50 : entity.pos.x - 50;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dx = target.pos.x - hitX;
                      const dy = (target.pos.y - 35) - hitY;

                      if (Math.sqrt(dx*dx + dy*dy) < ATTACK_RANGE) {
                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= ATTACK_DAMAGE;

                          // === 核心：强力击飞 ===
                          target.vel.x = entity.facingRight ? 15 : -15; // 水平击飞
                          target.vel.y = -8; // 垂直浮空
                          target.stunFrames = 20; // 硬直

                          shakeRef.current = 8;
                          spawnParticles(hitX, hitY, target.color, 12, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              // 死亡时更夸张的击飞
                              target.vel.x = entity.facingRight ? 25 : -25;
                              target.vel.y = -15;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });
          }
      }
    });

    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += p.gravity || 0;
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0);

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      // 竞技场风格背景
      ctx.fillStyle = '#1e1e2e';
      ctx.fillRect(0, 0, width, height);

      // 网格背景
      ctx.strokeStyle = '#313244';
      ctx.lineWidth = 2;
      const gridSize = 100;
      for (let x = 0; x < width; x += gridSize) {
          ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
      }
      for (let y = 0; y < height; y += gridSize) {
          ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
      }

      // 绘制平台
      ctx.fillStyle = '#45475a';
      ctx.strokeStyle = '#89b4fa';
      ctx.lineWidth = 3;

      PLATFORMS.forEach(plat => {
          ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
          ctx.strokeRect(plat.x, plat.y, plat.width, plat.height);
          // 平台装饰细节
          ctx.fillStyle = '#181825';
          for(let i=10; i<plat.width; i+=40) {
              ctx.fillRect(plat.x + i, plat.y + 5, 20, 10);
          }
          ctx.fillStyle = '#45475a';
      });

      // 地面
      ctx.fillStyle = '#11111b';
      ctx.fillRect(0, GROUND_Y, width, height - GROUND_Y);
      ctx.strokeStyle = '#a6e3a1';
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(0, GROUND_Y); ctx.lineTo(width, GROUND_Y); ctx.stroke();
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.1 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.8;
      }
      if (!entity.facingRight) ctx.scale(-1, 1);

      const color = entity.isLoser ? '#6c7086' : entity.color;
      ctx.strokeStyle = '#111'; // 黑色轮廓
      ctx.fillStyle = color;

      // 线条更粗，更像火柴人战斗风格
      ctx.lineWidth = 14; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      let headY = -70; let neckY = -55; let hipY = -30; 
      if (entity.isCrouching) { headY = -45; neckY = -30; hipY = -15; }

      // 绘制身体 (两层：黑色轮廓 + 彩色内芯)
      const drawBodyParts = (isOutline: boolean) => {
          ctx.lineWidth = isOutline ? 18 : 10;
          ctx.strokeStyle = isOutline ? '#000' : color;

          // 腿
          ctx.beginPath();
          if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
              ctx.moveTo(0, hipY); ctx.lineTo(-10, hipY + 45); 
              ctx.moveTo(0, hipY); ctx.lineTo(10, hipY + 45);  
          } else if (entity.isCrouching) {
              ctx.moveTo(0, hipY); ctx.lineTo(-20, -5); ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY); ctx.lineTo(20, -5); ctx.lineTo(10, 0);
          } else if (!entity.isGrounded) { // 空中姿态
              ctx.moveTo(0, hipY); ctx.lineTo(-15, 10); ctx.lineTo(-10, 25);
              ctx.moveTo(0, hipY); ctx.lineTo(20, 5); ctx.lineTo(25, 20);
          } else if (Math.abs(entity.vel.x) > 0.1) { // 跑步
              const runCycle = Math.sin(frameRef.current * 0.6);
              ctx.moveTo(0, hipY); ctx.lineTo(-20 * Math.cos(runCycle), 0);
              ctx.moveTo(0, hipY); ctx.lineTo(20 * Math.cos(runCycle), 0);
          } else {
              ctx.moveTo(0, hipY); ctx.lineTo(-12, 0);
              ctx.moveTo(0, hipY); ctx.lineTo(12, 0);
          }
          ctx.stroke();

          // 躯干
          ctx.beginPath(); ctx.moveTo(0, neckY); ctx.lineTo(0, hipY); ctx.stroke();

          // 手臂
          ctx.beginPath();
          if (entity.heldWeapon) {
               // 持枪姿态
               ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
               ctx.moveTo(0, neckY); ctx.lineTo(30, neckY - 5);
          } else if (entity.isAttacking) {
              const punchExtend = 35 + (entity.attackFrame * 2);
              ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
              ctx.moveTo(0, neckY); ctx.lineTo(punchExtend, neckY - 10);
          } else {
              ctx.moveTo(0, neckY); ctx.lineTo(20, neckY + 15); 
              ctx.moveTo(0, neckY); ctx.lineTo(-20, neckY + 15); 
          }
          ctx.stroke();
      };

      drawBodyParts(true);  // 轮廓
      drawBodyParts(false); // 颜色

      // 头部 (独立绘制)
      ctx.lineWidth = 4;
      ctx.strokeStyle = '#000';
      ctx.fillStyle = '#fff'; // 白脸
      ctx.beginPath();
      ctx.arc(0, headY, 18, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // 头带/眼罩 (区分P1 P2)
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.rect(-18, headY - 10, 36, 8);
      ctx.fill();
      // 飘带
      if (Math.abs(entity.vel.x) > 1 || entity.vel.y !== 0) {
          ctx.beginPath();
          ctx.moveTo(-18, headY - 6);
          ctx.lineTo(-40 - Math.random()*10, headY - 15);
          ctx.lineTo(-40 - Math.random()*10, headY + 5);
          ctx.fill();
      }

      // 武器绘制
      if (entity.heldWeapon) {
          ctx.translate(35, neckY - 5);
          if (entity.heldWeapon === 'pistol') {
              ctx.fillStyle = '#333';
              ctx.strokeStyle = '#111';
              ctx.lineWidth = 2;
              // 更酷的枪
              ctx.fillRect(-10, -5, 30, 8); 
              ctx.fillRect(-10, -5, 8, 15);
              ctx.fillStyle = '#555';
              ctx.fillRect(0, -5, 20, 4);
          } else {
              ctx.fillStyle = '#222';
              ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI*2); ctx.fill();
              ctx.fillStyle = '#f00'; ctx.font = '12px bold'; ctx.fillText('💣', -6, 4);
              // 导火索
              ctx.strokeStyle = '#fff'; ctx.beginPath(); ctx.moveTo(0, -12); ctx.lineTo(5, -20); ctx.stroke();
              ctx.fillStyle = '#ff9900'; ctx.fillRect(4, -22, 3, 3);
          }
      }

      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 震动处理
    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }
    ctx.save();
    ctx.translate(shakeX, shakeY);

    drawBackground(ctx, canvas.width, canvas.height);

    // 掉落物
    fallingItemsRef.current.forEach(item => {
        ctx.save();
        ctx.translate(item.pos.x, item.pos.y);

        if (!item.onGround) {
            // 降落伞
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(15, -50); ctx.moveTo(30, 0); ctx.lineTo(15, -50); ctx.stroke();
            ctx.fillStyle = '#ff6b6b'; ctx.beginPath(); ctx.arc(15, -50, 25, Math.PI, 0); ctx.fill();
        }

        // 武器箱发光
        ctx.shadowBlur = 10; ctx.shadowColor = '#ffd700';
        ctx.fillStyle = '#333'; ctx.fillRect(0, 0, 30, 30);
        ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 3; ctx.strokeRect(0, 0, 30, 30);
        ctx.font = '20px sans-serif'; ctx.textAlign = 'center'; ctx.fillText(item.type === 'pistol' ? '🔫' : '💣', 15, 22);
        ctx.restore();
    });

    // 投射物
    projectilesRef.current.forEach(p => {
        ctx.save();
        ctx.translate(p.pos.x, p.pos.y);
        if (p.type === 'pistol') {
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10; ctx.shadowColor = '#ffff00';
            ctx.fillRect(-6, -2, 12, 4);
        } else {
            ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
            if (frameRef.current % 8 < 4) { ctx.fillStyle = '#ff0000'; ctx.beginPath(); ctx.arc(3, -3, 3, 0, Math.PI*2); ctx.fill(); }
        }
        ctx.restore();
    });

    // 粒子
    particlesRef.current.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.life / p.maxLife;
        ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));
    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;
